/* Erzeugt von scripts/build-syntax-glossary.mjs aus content/syntax-glossary/. Nicht von Hand ändern. */
var RP_GLOSSARY=[{"id":"html","label":"HTML","codeLang":"html","intro":"Beschreibt Struktur und Bedeutung einer Seite. Zuerst das passende Element wählen, erst danach das Aussehen mit CSS.","notice":"Die Beispiele werden nicht ausgeführt. Zum Ausprobieren in eine .html-Datei kopieren und im Browser öffnen.","runner":"","entries":[{"id":"html-doc","cat":"Dokument","term":"<!doctype html> und Grundgerüst","syntax":"<!doctype html>\n<html lang=\"de\">…</html>","text":"Jede Seite beginnt mit dem Doctype. lang am html-Element nennt die Sprache (wichtig für Screenreader und Silbentrennung). Im head stehen Zeichensatz, Viewport und Titel.","code":"<!doctype html>\n<html lang=\"de\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Meine Seite</title>\n</head>\n<body>\n  <h1>Hallo</h1>\n</body>\n</html>","pitfall":"Ohne meta viewport wird die Seite auf Smartphones als verkleinerte Desktop-Seite gezeigt.","lesson":"html-m1-l1","tested":false},{"id":"html-headings","cat":"Struktur","term":"h1 bis h6","syntax":"<h1>…</h1> … <h6>…</h6>","text":"Überschriften gliedern die Seite. Es gibt eine h1 pro Seite, darunter folgen h2, h3 … ohne Ebenen zu überspringen.","code":"<h1>Rezepte</h1>\n<h2>Suppen</h2>\n<h3>Tomatensuppe</h3>","pitfall":"Überschriftenebenen nicht nach der Schriftgröße wählen. Größe bestimmt CSS, die Ebene die Struktur.","lesson":"html-m1-l2","tested":false},{"id":"html-landmarks","cat":"Struktur","term":"header, nav, main, footer, section, article","syntax":"<main>…</main>","text":"Semantische Bereiche statt <div>. main gibt es einmal pro Seite, nav enthält Navigation, article ist in sich abgeschlossen, section ein Themenabschnitt mit Überschrift.","code":"<header>…</header>\n<nav aria-label=\"Hauptnavigation\">…</nav>\n<main id=\"inhalt\">\n  <article>\n    <h2>Artikel</h2>\n  </article>\n</main>\n<footer>…</footer>","pitfall":"Gibt es mehrere nav-Bereiche, braucht jeder ein eigenes aria-label, damit Screenreader sie unterscheiden können.","lesson":"html-m1-l2","tested":false},{"id":"html-text","cat":"Text","term":"p, strong, em, code","syntax":"<p>…</p>    <strong>…</strong>    <em>…</em>","text":"p ist ein Absatz. strong markiert wichtige Stellen, em betont. code zeigt Quelltext. Zeilenumbrüche setzt man nicht mit <br> zur Abstandsgestaltung.","code":"<p>Das ist <strong>wichtig</strong> und das <em>betont</em>. Befehl: <code>git status</code></p>","pitfall":"Nicht <b> und <i> verwenden, nur um etwas fett oder kursiv darzustellen. Sie tragen keine Bedeutung.","lesson":"html-m1-l2","tested":false},{"id":"html-link","cat":"Links und Medien","term":"a (Link)","syntax":"<a href=\"ziel\">Text</a>","text":"Link zu einer anderen Seite, Datei oder Stelle (#anker). Der Linktext soll das Ziel beschreiben. Für Aktionen ohne Navigation gehört stattdessen ein <button> hin.","code":"<a href=\"/kontakt\">Kontakt aufnehmen</a>\n<a href=\"https://example.org\" rel=\"noopener\" target=\"_blank\">Beispiel (neues Fenster)</a>","pitfall":"Linktexte wie „hier klicken“ sagen Screenreader-Nutzern nichts. Bei target=\"_blank\" den Hinweis „neues Fenster“ in den Text aufnehmen.","lesson":"html-m1-l3","tested":false},{"id":"html-lists","cat":"Text","term":"ul, ol, li","syntax":"<ul><li>…</li></ul>","text":"ul ist eine Liste ohne Reihenfolge, ol eine nummerierte Liste. Direkte Kinder sind nur li-Elemente.","code":"<ol>\n  <li>Wasser kochen</li>\n  <li>Nudeln hinzufügen</li>\n</ol>","pitfall":"Navigationen sind Listen von Links. Das als ul in nav auszuzeichnen hilft Screenreadern beim Zählen der Einträge.","lesson":"html-m1-l3","tested":false},{"id":"html-img","cat":"Links und Medien","term":"img","syntax":"<img src=\"datei.jpg\" alt=\"Beschreibung\" width=\"800\" height=\"600\">","text":"Bindet ein Bild ein. alt beschreibt den Inhalt, bei rein dekorativen Bildern bleibt es leer (alt=\"\"). width und height verhindern Layout-Sprünge. loading=\"lazy\" lädt Bilder unterhalb des sichtbaren Bereichs später.","code":"<img src=\"team.jpg\" alt=\"Das Team vor dem Büro\" width=\"800\" height=\"600\" loading=\"lazy\">","pitfall":"Das wichtigste Bild am Seitenanfang (LCP) niemals lazy laden. Das verzögert die Anzeige.","lesson":"html-m1-l3","tested":false},{"id":"html-button","cat":"Formulare","term":"button","syntax":"<button type=\"button\">Text</button>","text":"Schaltfläche für Aktionen. Ohne type innerhalb eines Formulars sendet sie das Formular ab. Mit type=\"button\" tut sie das nicht.","code":"<button type=\"button\">Menü öffnen</button>\n<button type=\"submit\">Absenden</button>","pitfall":"Kein <div onclick>. Der <button> ist per Tastatur bedienbar und für Screenreader erkennbar, das <div> nicht.","lesson":"html-m1-l4","tested":false},{"id":"html-form","cat":"Formulare","term":"form, label, input","syntax":"<label for=\"id\">Text</label>\n<input id=\"id\" name=\"feld\" type=\"…\">","text":"Jedes Feld hat ein sichtbares label, das per for mit der id des Felds verbunden ist. type wählt die Eingabeart (text, email, number, date, password …), name bestimmt den Parameternamen beim Senden.","code":"<form method=\"post\" action=\"/anmelden\">\n  <label for=\"mail\">E-Mail-Adresse</label>\n  <input id=\"mail\" name=\"email\" type=\"email\" autocomplete=\"email\" required>\n  <button type=\"submit\">Anmelden</button>\n</form>","pitfall":"placeholder ist kein Ersatz für ein label. Er verschwindet beim Tippen und hat oft zu wenig Kontrast.","lesson":"html-m1-l4","tested":false},{"id":"html-validation","cat":"Formulare","term":"required, pattern, min, max, minlength","syntax":"<input required minlength=\"8\" pattern=\"[0-9]{5}\">","text":"Native Prüfregeln. Der Browser zeigt Fehlermeldungen und verhindert das Absenden. Sie ersetzen nicht die Prüfung auf dem Server.","code":"<label for=\"plz\">Postleitzahl</label>\n<input id=\"plz\" name=\"plz\" inputmode=\"numeric\" pattern=\"[0-9]{5}\" required>","pitfall":"Die Browser-Prüfung lässt sich umgehen. Der Server muss immer erneut prüfen.","lesson":"html-m1-l4","tested":false},{"id":"html-select","cat":"Formulare","term":"select, textarea, fieldset","syntax":"<select>…</select>    <textarea>…</textarea>    <fieldset><legend>…</legend></fieldset>","text":"select bietet eine Auswahl, textarea mehrzeiligen Text. fieldset mit legend fasst zusammengehörende Felder (z. B. Radiobuttons) zu einer benannten Gruppe zusammen.","code":"<fieldset>\n  <legend>Zahlungsart</legend>\n  <label><input type=\"radio\" name=\"zahlung\" value=\"karte\"> Karte</label>\n  <label><input type=\"radio\" name=\"zahlung\" value=\"rechnung\"> Rechnung</label>\n</fieldset>","pitfall":"Radiobuttons mit demselben name bilden eine Gruppe. Ohne gemeinsamen name lassen sich mehrere gleichzeitig wählen.","lesson":"html-m1-l4","tested":false},{"id":"html-table","cat":"Tabellen","term":"table, th, td","syntax":"<table><caption>…</caption><thead>…</thead><tbody>…</tbody></table>","text":"Tabellen sind für Daten gedacht, nicht fürs Layout. caption beschreibt sie, th mit scope=\"col\" oder \"row\" kennzeichnet Überschriftenzellen.","code":"<table>\n  <caption>Preise</caption>\n  <thead>\n    <tr><th scope=\"col\">Artikel</th><th scope=\"col\">Preis</th></tr>\n  </thead>\n  <tbody>\n    <tr><th scope=\"row\">Tee</th><td>3,50 €</td></tr>\n  </tbody>\n</table>","pitfall":"Auf schmalen Bildschirmen laufen breite Tabellen über. Sie in einen Container mit overflow-x: auto setzen.","lesson":"html-m1-l5","tested":false},{"id":"html-aria","cat":"Barrierefreiheit","term":"aria-label und aria-describedby","syntax":"<button aria-label=\"Menü schließen\">✕</button>","text":"ARIA ergänzt Namen und Beziehungen, wenn natives HTML nicht reicht. aria-label benennt Elemente ohne sichtbaren Text, aria-describedby verknüpft Hilfe- oder Fehlertexte mit einem Feld.","code":"<label for=\"pw\">Passwort</label>\n<input id=\"pw\" type=\"password\" aria-describedby=\"pw-hilfe\">\n<p id=\"pw-hilfe\">Mindestens 12 Zeichen.</p>","pitfall":"Kein ARIA ist besser als falsches ARIA. Erst prüfen, ob ein natives Element (button, label, nav) die Aufgabe schon erfüllt.","lesson":"html-m1-l5","tested":false},{"id":"html-meta","cat":"Dokument","term":"link und script","syntax":"<link rel=\"stylesheet\" href=\"stil.css\">\n<script src=\"app.js\" defer></script>","text":"link bindet Stylesheets ein, script bindet JavaScript ein. defer lädt das Skript parallel und führt es nach dem Parsen aus. type=\"module\" lädt ES-Module.","code":"<link rel=\"stylesheet\" href=\"stil.css\">\n<script type=\"module\" src=\"app.js\"></script>","pitfall":"Skripte ohne defer oder type=\"module\" blockieren den Seitenaufbau. Dadurch sinkt die Ladegeschwindigkeit.","lesson":"html-m1-l1","tested":false}]},{"id":"css","label":"CSS","codeLang":"css","intro":"Gestaltet HTML. Eine Regel besteht aus Selektor und Deklarationen: selektor { eigenschaft: wert; }","notice":"Die Beispiele werden nicht ausgeführt. Zum Ausprobieren in ein Stylesheet kopieren und mit einer HTML-Seite verbinden.","runner":"","entries":[{"id":"css-selectors","cat":"Selektoren","term":"Element-, Klassen- und ID-Selektor","syntax":"p { … }    .klasse { … }    #id { … }","text":"Ein Elementselektor trifft alle Elemente dieses Typs, .klasse trifft alle mit class=\"klasse\", #id genau ein Element. In der Praxis arbeitet man überwiegend mit Klassen.","code":"p { color: #222; }\n.karte { padding: 1rem; }\n#kopf { position: sticky; top: 0; }","pitfall":"ID-Selektoren sind sehr spezifisch und lassen sich schwer überschreiben. Für Gestaltung besser Klassen nehmen.","lesson":"css-m1-l1","tested":false},{"id":"css-combinators","cat":"Selektoren","term":"Kombinatoren","syntax":"a b    a > b    a + b    a ~ b","text":"Leerzeichen trifft Nachfahren, > nur direkte Kinder, + das unmittelbar folgende Geschwister, ~ alle folgenden Geschwister.","code":"nav a { text-decoration: none; }\nul > li { margin-block: .25rem; }\nh2 + p { font-size: 1.1rem; }","pitfall":"Lange Selektorketten (a b c d) koppeln CSS stark ans HTML. Besser eine Klasse am Zielelement vergeben.","lesson":"css-m1-l1","tested":false},{"id":"css-pseudo","cat":"Selektoren","term":"Pseudoklassen","syntax":":hover  :focus-visible  :first-child  :not(…)  :has(…)","text":"Wählen Elemente nach Zustand oder Position. :focus-visible zeigt den Fokus bei Tastaturbedienung, :has() wählt Elemente nach ihrem Inhalt, :not() schließt aus.","code":"a:hover { text-decoration: underline; }\n:focus-visible { outline: 3px solid #1a5fb4; outline-offset: 2px; }\n.karte:has(img) { display: grid; }","pitfall":"Den Fokusrahmen nie mit outline: none entfernen, ohne einen sichtbaren Ersatz zu liefern. Tastaturnutzer verlieren sonst die Orientierung.","lesson":"css-m1-l3","tested":false},{"id":"css-specificity","cat":"Kaskade","term":"Spezifität und Reihenfolge","syntax":"Inline > ID > Klasse/Attribut/Pseudoklasse > Element","text":"Treffen mehrere Regeln dasselbe Element, gewinnt die spezifischere. Bei gleicher Spezifität gilt die spätere. !important schaltet diese Ordnung aus und sollte vermieden werden.","code":"p { color: black; }\n.hinweis { color: blue; }      /* gewinnt gegen p */\n.hinweis { color: green; }     /* gewinnt gegen die vorige Regel */","pitfall":"Wer mit !important gegen !important kämpft, hat ein Strukturproblem. Besser Selektoren vereinfachen oder @layer verwenden.","lesson":"css-m1-l1","tested":false},{"id":"css-custom-props","cat":"Kaskade","term":"Custom Properties (var)","syntax":":root { --farbe: #1a5fb4; }    color: var(--farbe, schwarz);","text":"Eigene Variablen mit Namen, die mit -- beginnen. Sie werden vererbt und lassen sich je Bereich überschreiben. Gut für Farben, Abstände und Schriften.","code":":root {\n  --abstand: 1rem;\n  --akzent: #1a5fb4;\n}\n.knopf {\n  padding: var(--abstand);\n  background: var(--akzent);\n}","pitfall":"Custom Properties sind erst zur Laufzeit gültig. Ein Tippfehler im Namen ergibt keinen Fehler, nur einen leeren Wert.","lesson":"css-m1-l1","tested":false},{"id":"css-boxmodel","cat":"Boxmodell","term":"margin, padding, border, box-sizing","syntax":"box-sizing: border-box;","text":"Jedes Element ist eine Box: Inhalt, Innenabstand (padding), Rand (border), Außenabstand (margin). Mit box-sizing: border-box zählen padding und border zur angegebenen Breite.","code":"*, *::before, *::after { box-sizing: border-box; }\n.karte {\n  padding: 1rem;\n  border: 1px solid #ccc;\n  margin-block: 1.5rem;\n}","pitfall":"Vertikale Außenabstände zweier Geschwister verschmelzen („Margin Collapsing“). Der größere gewinnt, sie addieren sich nicht.","lesson":"css-m1-l2","tested":false},{"id":"css-units","cat":"Boxmodell","term":"Einheiten: rem, em, %, vw, ch","syntax":"font-size: 1rem;    width: min(100%, 70ch);","text":"rem bezieht sich auf die Basisschrift der Seite, em auf die des Elements, % auf das Elternelement, vw auf die Fensterbreite, ch auf die Breite einer „0“. Relative Einheiten respektieren die Einstellungen der Nutzer.","code":"body { font-size: 1rem; }\n.text { max-width: 70ch; }\nh1 { font-size: clamp(1.6rem, 4vw, 2.6rem); }","pitfall":"Schriftgrößen in px ignorieren die Schriftgröße-Einstellung des Browsers. Für Text rem verwenden.","lesson":"css-m1-l2","tested":false},{"id":"css-color-font","cat":"Typografie","term":"color, font-family, line-height","syntax":"font: 1rem/1.6 system-ui;","text":"color setzt die Textfarbe, font-family die Schriftart (mit Ersatzschriften), line-height den Zeilenabstand. Ein Zeilenabstand von etwa 1,5 liest sich gut.","code":"body {\n  font-family: \"IBM Plex Sans\", system-ui, sans-serif;\n  line-height: 1.6;\n  color: #1d1d1f;\n}","pitfall":"Textkontrast mindestens 4,5:1 (WCAG AA), bei großer Schrift 3:1. Hellgrau auf Weiß fällt oft durch.","lesson":"css-m1-l3","tested":false},{"id":"css-display","cat":"Layout","term":"display","syntax":"display: block | inline | inline-block | flex | grid | none","text":"Bestimmt, wie sich ein Element ins Layout einfügt. none blendet es samt Platz und aus dem Zugänglichkeitsbaum aus. flex und grid aktivieren die modernen Layoutmodelle für die Kinder.","code":".nav { display: flex; gap: 1rem; }\n.galerie { display: grid; }\n.nur-screenreader { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }","pitfall":"display: none versteckt auch vor Screenreadern. Für Inhalte, die nur sie hören sollen, die Technik „visually hidden“ wie oben verwenden.","lesson":"css-m1-l4","tested":false},{"id":"css-flex","cat":"Layout","term":"Flexbox","syntax":"display: flex; justify-content: …; align-items: …; gap: …; flex-wrap: wrap;","text":"Ordnet Kinder in einer Reihe oder Spalte an (eindimensional). justify-content verteilt entlang der Hauptachse, align-items auf der Querachse, gap setzt Abstände, flex-wrap erlaubt Zeilenumbruch.","code":".leiste {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 1rem;\n  justify-content: space-between;\n  align-items: center;\n}\n.leiste .wachsen { flex: 1 1 12rem; }","pitfall":"Flex-Kinder schrumpfen nicht unter ihre Inhaltsbreite. Langer Text oder Code braucht min-width: 0 am Kind, sonst läuft die Seite über.","lesson":"css-m1-l4","tested":false},{"id":"css-grid","cat":"Layout","term":"Grid","syntax":"display: grid; grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));","text":"Zweidimensionales Raster aus Zeilen und Spalten. Mit auto-fit und minmax entstehen Kartenlayouts, die sich ohne Media Queries der Breite anpassen.","code":".karten {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr));\n  gap: 1rem;\n}","pitfall":"minmax(16rem, 1fr) ohne min(100%, …) kann auf sehr schmalen Bildschirmen zu Überlauf führen.","lesson":"css-m1-l5","tested":false},{"id":"css-position","cat":"Layout","term":"position","syntax":"position: static | relative | absolute | fixed | sticky","text":"relative verschiebt relativ zur normalen Position und dient als Bezug für absolute Kinder. fixed klebt am Fenster, sticky haftet beim Scrollen an einer Kante.","code":".badge-container { position: relative; }\n.badge { position: absolute; top: 0; right: 0; }\n.kopf { position: sticky; top: 0; }","pitfall":"Fixierte Kopfzeilen können Ankerziele und Fokus verdecken. scroll-margin-top und ausreichend Platz einplanen.","lesson":"css-m1-l5","tested":false},{"id":"css-media","cat":"Responsiv","term":"@media","syntax":"@media (min-width: 40rem) { … }","text":"Wendet Regeln nur unter bestimmten Bedingungen an. Mobile First: zuerst das Smartphone-Layout schreiben, mit min-width nach oben erweitern. Auch Nutzereinstellungen wie prefers-reduced-motion und prefers-color-scheme lassen sich abfragen.","code":".karten { display: grid; gap: 1rem; }\n@media (min-width: 48rem) {\n  .karten { grid-template-columns: 1fr 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  * { animation: none !important; transition: none !important; }\n}","pitfall":"Breakpoints nach dem Inhalt wählen, nicht nach Geräten. Bricht das Layout bei 41rem, ist dort der richtige Breakpoint.","lesson":"css-m1-l6","tested":false},{"id":"css-transition","cat":"Bewegung","term":"transition und transform","syntax":"transition: transform .2s ease;","text":"Lässt eine Änderung weich ablaufen. Am besten werden nur transform und opacity animiert, da sie wenig Rechenaufwand verursachen.","code":".knopf { transition: transform .15s ease; }\n.knopf:hover { transform: translateY(-2px); }\n@media (prefers-reduced-motion: reduce) {\n  .knopf { transition: none; }\n}","pitfall":"Bewegung muss abschaltbar sein. Nutzer mit Vestibularstörungen stellen „Bewegung reduzieren“ ein. Das berücksichtigt prefers-reduced-motion.","lesson":"css-m1-l6","tested":false},{"id":"css-clamp","cat":"Responsiv","term":"clamp, min, max","syntax":"clamp(minimum, bevorzugt, maximum)","text":"Begrenzt einen Wert zwischen zwei Grenzen. So wächst eine Schrift oder ein Abstand flüssig mit der Fensterbreite, bleibt aber lesbar.","code":"h1 { font-size: clamp(1.75rem, 1rem + 3vw, 3rem); }\n.container { width: min(100% - 2rem, 70rem); margin-inline: auto; }","pitfall":"Rein vw-basierte Schrift lässt sich nicht mit Browser-Zoom vergrößern. Immer einen rem-Anteil beimischen, wie oben.","lesson":"css-m1-l6","tested":false},{"id":"css-image","cat":"Responsiv","term":"max-width und aspect-ratio für Bilder","syntax":"img { max-width: 100%; height: auto; }","text":"Verhindert, dass Bilder breiter als ihr Container werden. aspect-ratio hält das Seitenverhältnis stabil, object-fit schneidet Bilder passend zu.","code":"img { max-width: 100%; height: auto; display: block; }\n.vorschau { aspect-ratio: 16 / 9; object-fit: cover; width: 100%; }","pitfall":"Mit object-fit: cover werden Bildränder abgeschnitten. Wichtige Inhalte können dadurch verschwinden.","lesson":"css-m1-l6","tested":false}]},{"id":"js","label":"JavaScript / TypeScript","codeLang":"javascript","intro":"Sprache des Browsers und von Node.js. TypeScript ergänzt Typen, die vor dem Ausführen entfernt werden.","notice":"Die Beispiele sind mit Node.js 22 ausgeführt und geprüft. Browser-Beispiele (DOM, fetch, localStorage) sowie Import und Export werden nur gezeigt, nicht ausgeführt.","runner":"Node.js","entries":[{"id":"js-const","cat":"Variablen","term":"const","syntax":"const name = wert;","text":"Legt eine Variable an, die nicht neu zugewiesen werden kann. Das ist die Standardwahl. Bei Objekten und Arrays bleibt der Inhalt veränderbar, nur die Bindung ist fest.","code":"const preis = 20;\nconst liste = [1, 2];\nliste.push(3);\nconsole.log(preis, liste);","out":"20 [ 1, 2, 3 ]","pitfall":"const macht Objekte nicht unveränderlich. Wer den Inhalt schützen will, braucht Object.freeze oder kopiert statt zu verändern.","lesson":"js-m1-l1","tested":true},{"id":"js-let","cat":"Variablen","term":"let","syntax":"let name = wert;","text":"Legt eine Variable an, die später einen neuen Wert bekommen darf. Sie gilt nur im Block { … }, in dem sie steht.","code":"let zaehler = 0;\nfor (let i = 0; i < 3; i++) {\n  zaehler += i;\n}\nconsole.log(zaehler);","out":"3","pitfall":"Nur let verwenden, wenn sich der Wert wirklich ändert. Sonst const.","lesson":"js-m1-l1","tested":true},{"id":"js-var","cat":"Variablen","term":"var","syntax":"var name = wert;","text":"Alte Form der Variablendeklaration. Sie gilt in der ganzen Funktion statt nur im Block und wird nach oben „gehoben“. In neuem Code nicht mehr verwenden.","code":"if (true) {\n  var innen = 'sichtbar';\n}\nconsole.log(innen);","out":"sichtbar","pitfall":"Mit let oder const wäre innen außerhalb des Blocks nicht erreichbar. Genau diese Überraschung vermeiden die neuen Schlüsselwörter.","lesson":"js-m1-l1","tested":true},{"id":"js-typeof","cat":"Typen und Werte","term":"typeof","syntax":"typeof wert","text":"Liefert den Typ eines Werts als Text: \"string\", \"number\", \"boolean\", \"undefined\", \"object\", \"function\", \"bigint\" oder \"symbol\".","code":"console.log(typeof 'a', typeof 1, typeof null, typeof [], typeof (() => 1));","out":"string number object object function","pitfall":"typeof null ist \"object\" (alter Fehler der Sprache), und Arrays sind ebenfalls \"object\". Arrays erkennt man mit Array.isArray.","lesson":"js-m1-l1","tested":true},{"id":"js-equality","cat":"Typen und Werte","term":"=== und !==","syntax":"a === b","text":"Strikter Vergleich: Wert und Typ müssen übereinstimmen. Der lockere Vergleich == wandelt vorher Typen um und liefert Überraschungen.","code":"console.log(1 === '1', 1 == '1', null === undefined, null == undefined);","out":"false true false true","pitfall":"Immer === und !== benutzen. == ist nur bei „x == null“ (null oder undefined) bewusst sinnvoll.","lesson":"js-m1-l1","tested":true},{"id":"js-nullish","cat":"Typen und Werte","term":"?? und ?.","syntax":"a ?? b    obj?.eigenschaft","text":"?? liefert den rechten Wert nur, wenn links null oder undefined steht. ?. liest eine Eigenschaft nur, wenn das Objekt davor existiert, sonst kommt undefined.","code":"const nutzer = { name: 'Mia', adresse: null };\nconsole.log(nutzer.adresse?.ort);\nconsole.log(0 ?? 10, 0 || 10);","out":"undefined\n0 10","pitfall":"|| ersetzt auch 0, \"\" und false durch den Standardwert. Für „fehlt“ statt „falsy“ ?? verwenden.","lesson":"js-m1-l1","tested":true},{"id":"js-template","cat":"Typen und Werte","term":"Template-String","syntax":"`Text ${ausdruck}`","text":"Text in Backticks, in den mit ${…} beliebige Ausdrücke eingesetzt werden. Er darf über mehrere Zeilen gehen.","code":"const name = 'Ada';\nconsole.log(`Hallo ${name}, 2 + 3 = ${2 + 3}`);","out":"Hallo Ada, 2 + 3 = 5","pitfall":"Nutzereingaben nie ungeprüft per Template-String in HTML oder SQL setzen. Das führt zu XSS bzw. SQL-Injection.","lesson":"js-m1-l1","tested":true},{"id":"js-if","cat":"Kontrollfluss","term":"if / else","syntax":"if (bedingung) { … } else if (…) { … } else { … }","text":"Führt einen Block nur aus, wenn die Bedingung wahr ist. Falsy sind false, 0, \"\", null, undefined, NaN; alles andere ist truthy.","code":"const punkte = 72;\nif (punkte >= 90) console.log('sehr gut');\nelse if (punkte >= 70) console.log('gut');\nelse console.log('weiter üben');","out":"gut","pitfall":"Auch bei einer Zeile geschweifte Klammern setzen, sonst gehört eine später ergänzte Zeile nicht zum Block.","lesson":"js-m1-l1","tested":true},{"id":"js-ternary","cat":"Kontrollfluss","term":"Bedingungsoperator","syntax":"bedingung ? wennWahr : wennFalsch","text":"Kurzform von if/else, die einen Wert liefert. Passt für einfache Auswahl innerhalb eines Ausdrucks.","code":"const alter = 17;\nconsole.log(alter >= 18 ? 'volljährig' : 'minderjährig');","out":"minderjährig","pitfall":"Verschachtelte Bedingungsoperatoren sind schwer lesbar; dann besser if/else oder eine Funktion.","lesson":"js-m1-l1","tested":true},{"id":"js-switch","cat":"Kontrollfluss","term":"switch","syntax":"switch (wert) { case a: …; break; default: … }","text":"Wählt anhand eines Werts einen von mehreren Fällen. Ohne break läuft die Ausführung in den nächsten Fall weiter.","code":"const tag = 'sa';\nswitch (tag) {\n  case 'sa':\n  case 'so':\n    console.log('Wochenende');\n    break;\n  default:\n    console.log('Werktag');\n}","out":"Wochenende","pitfall":"Vergessenes break ist die häufigste Fehlerquelle. Das gezielte Durchfallen (sa/so oben) sollte ein Kommentar erklären.","lesson":"js-m1-l1","tested":true},{"id":"js-for","cat":"Schleifen","term":"for","syntax":"for (let i = 0; i < n; i++) { … }","text":"Zählschleife mit Startwert, Bedingung und Schritt. Gut, wenn der Index gebraucht wird.","code":"for (let i = 1; i <= 3; i++) {\n  console.log(i * i);\n}","out":"1\n4\n9","pitfall":"Mit <= statt < läuft die Schleife einmal zu oft (Off-by-one). Beim Arbeiten mit Arrays bis i < liste.length zählen.","lesson":"js-m1-l1","tested":true},{"id":"js-for-of","cat":"Schleifen","term":"for … of","syntax":"for (const element of sammlung) { … }","text":"Läuft über die Elemente von Arrays, Strings, Maps und Sets. Kein Index nötig.","code":"for (const farbe of ['rot', 'grün']) {\n  console.log(farbe);\n}","out":"rot\ngrün","pitfall":"for … in läuft über die Schlüssel (bei Arrays die Indizes als Text) und gehört nicht zu Arrays. Für Elemente for … of.","lesson":"js-m1-l1","tested":true},{"id":"js-function","cat":"Funktionen","term":"function","syntax":"function name(parameter) { return wert; }","text":"Benannte Funktion. Sie wird nach oben gehoben und kann deshalb vor der Deklaration aufgerufen werden. Ohne return liefert sie undefined.","code":"function summe(a, b = 0) {\n  return a + b;\n}\nconsole.log(summe(2, 3), summe(5));","out":"5 5","pitfall":"Standardwerte (b = 0) greifen nur bei undefined, nicht bei null.","lesson":"js-m1-l2","tested":true},{"id":"js-arrow","cat":"Funktionen","term":"Pfeilfunktion","syntax":"(a, b) => a + b","text":"Kurzschreibweise für Funktionen. Ohne geschweifte Klammern ist der Ausdruck der Rückgabewert. Pfeilfunktionen haben kein eigenes this.","code":"const verdopple = (x) => x * 2;\nconsole.log([1, 2, 3].map(verdopple));","out":"[ 2, 4, 6 ]","pitfall":"Ein Objekt direkt zurückgeben braucht Klammern: () => ({ a: 1 }). Ohne sie liest JavaScript { … } als Funktionskörper.","lesson":"js-m1-l2","tested":true},{"id":"js-closure","cat":"Funktionen","term":"Closure","syntax":"function außen() { let x; return () => x; }","text":"Eine Funktion merkt sich die Variablen ihrer Umgebung, auch nachdem die äußere Funktion beendet ist.","code":"function zaehler() {\n  let n = 0;\n  return () => ++n;\n}\nconst naechster = zaehler();\nnaechster();\nconsole.log(naechster());","out":"2","pitfall":"Jede Closure hält ihre Daten im Speicher. Lang lebende Closures mit großen Objekten können Speicher binden.","lesson":"js-m1-l2","tested":true},{"id":"js-rest-spread","cat":"Funktionen","term":"Rest und Spread","syntax":"...liste","text":"Spread (...) verteilt Elemente eines Arrays oder Objekts in ein neues. Rest (...) sammelt übrige Parameter oder Elemente in einem Array.","code":"const a = [1, 2];\nconst b = [...a, 3];\nconst o = { ...{ x: 1 }, y: 2 };\nconst summe = (...zahlen) => zahlen.reduce((s, z) => s + z, 0);\nconsole.log(b, o, summe(1, 2, 3));","out":"[ 1, 2, 3 ] { x: 1, y: 2 } 6","pitfall":"Spread kopiert nur die oberste Ebene. Verschachtelte Objekte teilen sich weiter dieselbe Referenz.","lesson":"js-m1-l3","tested":true},{"id":"js-destructuring","cat":"Objekte und Arrays","term":"Destructuring","syntax":"const { a, b } = obj;    const [x, y] = liste;","text":"Entpackt Eigenschaften eines Objekts oder Elemente eines Arrays direkt in Variablen. Mit = lassen sich Standardwerte setzen, mit : umbenennen.","code":"const nutzer = { name: 'Mia', alter: 30 };\nconst { name, rolle = 'Gast' } = nutzer;\nconst [erstes, zweites] = ['a', 'b'];\nconsole.log(name, rolle, erstes, zweites);","out":"Mia Gast a b","pitfall":"Bei Objekten zählen die Namen, bei Arrays die Position. Fehlt die Eigenschaft, entsteht undefined, kein Fehler.","lesson":"js-m1-l3","tested":true},{"id":"js-object-literal","cat":"Objekte und Arrays","term":"Objekt-Literal","syntax":"{ schluessel: wert, kurz, [berechnet]: 1 }","text":"Fasst benannte Werte zusammen. Kurzschreibweise: { name } ist { name: name }. Eckige Klammern berechnen den Schlüssel.","code":"const name = 'Ada';\nconst feld = 'rolle';\nconst o = { name, [feld]: 'Admin' };\nconsole.log(o);","out":"{ name: 'Ada', rolle: 'Admin' }","pitfall":"Objekte werden als Referenz weitergegeben. Zwei Variablen können dasselbe Objekt meinen, eine Änderung wirkt auf beide.","lesson":"js-m1-l3","tested":true},{"id":"js-array-map","cat":"Objekte und Arrays","term":"map","syntax":"liste.map((element, index) => neuerWert)","text":"Erzeugt ein neues Array, indem jedes Element durch eine Funktion umgewandelt wird. Die Länge bleibt gleich, das Original bleibt unverändert.","code":"console.log([1, 2, 3].map((n) => n * 10));","out":"[ 10, 20, 30 ]","pitfall":"map für Umwandlungen nutzen, nicht nur für Nebenwirkungen. Dafür gibt es forEach oder for … of.","lesson":"js-m1-l3","tested":true},{"id":"js-array-filter","cat":"Objekte und Arrays","term":"filter","syntax":"liste.filter((element) => bedingung)","text":"Liefert ein neues Array mit den Elementen, für die die Funktion einen wahren Wert zurückgibt.","code":"console.log([5, 12, 8, 20].filter((n) => n > 9));","out":"[ 12, 20 ]","pitfall":"Das Ergebnis ist immer ein Array, auch wenn nichts passt (dann leer). Für genau ein Element find verwenden.","lesson":"js-m1-l3","tested":true},{"id":"js-array-reduce","cat":"Objekte und Arrays","term":"reduce","syntax":"liste.reduce((summe, element) => …, startwert)","text":"Faltet ein Array zu einem einzelnen Wert zusammen, etwa Summe, Zähltabelle oder Objekt.","code":"const summe = [1, 2, 3, 4].reduce((s, n) => s + n, 0);\nconsole.log(summe);","out":"10","pitfall":"Den Startwert immer angeben. Ohne ihn schlägt reduce bei einem leeren Array mit einem Fehler fehl.","lesson":"js-m1-l3","tested":true},{"id":"js-array-find","cat":"Objekte und Arrays","term":"find, some, every, includes","syntax":"liste.find(fn)    liste.some(fn)    liste.includes(wert)","text":"find liefert das erste passende Element (oder undefined). some fragt „mindestens eins?“, every fragt „alle?“, includes prüft auf einen konkreten Wert.","code":"const z = [3, 8, 15];\nconsole.log(z.find((n) => n > 5), z.some((n) => n > 10), z.every((n) => n > 5), z.includes(8));","out":"8 true false true","pitfall":"find liefert das Element selbst, nicht den Index. Der Index kommt aus findIndex.","lesson":"js-m1-l3","tested":true},{"id":"js-array-sort","cat":"Objekte und Arrays","term":"sort","syntax":"liste.sort((a, b) => a - b)    liste.toSorted(…)","text":"Sortiert ein Array. Ohne Vergleichsfunktion wird als Text sortiert. toSorted liefert ein sortiertes Array, ohne das Original zu verändern.","code":"const z = [10, 9, 1];\nconsole.log(z.toSorted(), z.toSorted((a, b) => a - b), z);","out":"[ 1, 10, 9 ] [ 1, 9, 10 ] [ 10, 9, 1 ]","pitfall":"sort verändert das Array direkt. Ohne Vergleichsfunktion steht 10 vor 9, weil Text verglichen wird.","lesson":"js-m1-l3","tested":true},{"id":"js-map-set","cat":"Objekte und Arrays","term":"Map und Set","syntax":"new Map([[k, v]])    new Set([…])","text":"Map speichert Schlüssel-Wert-Paare mit beliebigen Schlüsseln und merkt sich die Einfügereihenfolge. Set speichert jeden Wert höchstens einmal.","code":"const m = new Map([['a', 1]]);\nm.set('b', 2);\nconst s = new Set([1, 1, 2]);\nconsole.log(m.get('b'), m.size, [...s]);","out":"2 2 [ 1, 2 ]","pitfall":"JSON.stringify kennt weder Map noch Set und liefert {}. Vorher in Array oder Objekt umwandeln.","lesson":"js-m1-l3","tested":true},{"id":"js-class","cat":"Objekte und Arrays","term":"class","syntax":"class Name { constructor() {} methode() {} }","text":"Vorlage für Objekte mit Eigenschaften und Methoden. extends erbt von einer anderen Klasse; #feld ist wirklich privat.","code":"class Konto {\n  #stand = 0;\n  einzahlen(betrag) { this.#stand += betrag; return this; }\n  get stand() { return this.#stand; }\n}\nconsole.log(new Konto().einzahlen(50).stand);","out":"50","pitfall":"this hängt vom Aufruf ab. Eine Methode als Callback übergeben verliert this, sofern sie nicht gebunden oder als Pfeilfunktion definiert wird.","lesson":"js-m1-l3","tested":true},{"id":"js-this","cat":"Objekte und Arrays","term":"this","syntax":"this.eigenschaft","text":"Verweist in einer Methode auf das Objekt, an dem sie aufgerufen wurde. Bei Pfeilfunktionen wird this von außen übernommen.","code":"const o = {\n  name: 'Ada',\n  sagHallo() { return 'Hallo ' + this.name; },\n};\nconst lose = o.sagHallo;\nconsole.log(o.sagHallo());\ntry { lose(); } catch (e) { console.log('Fehler:', e.constructor.name); }","out":"Hallo Ada\nFehler: TypeError","pitfall":"Eine herausgelöste Methode verliert ihr Objekt. Abhilfe: o.sagHallo.bind(o) oder eine Pfeilfunktion als Wrapper.","lesson":"js-m1-l3","tested":true},{"id":"js-json","cat":"Daten","term":"JSON.stringify und JSON.parse","syntax":"JSON.stringify(wert)    JSON.parse(text)","text":"Wandelt Werte in JSON-Text um und zurück. So werden Daten gespeichert oder über das Netz geschickt.","code":"const text = JSON.stringify({ a: 1, b: [true, null] });\nconsole.log(text);\nconsole.log(JSON.parse(text).b[0]);","out":"{\"a\":1,\"b\":[true,null]}\ntrue","pitfall":"JSON.parse wirft bei ungültigem Text einen Fehler. Daten von außen in try/catch parsen und danach prüfen, nicht blind vertrauen.","lesson":"js-m1-l5","tested":true},{"id":"js-try-catch","cat":"Fehler","term":"try / catch / finally","syntax":"try { … } catch (fehler) { … } finally { … }","text":"Fängt Fehler, die im try-Block geworfen werden. finally läuft immer, auch nach einem Fehler oder return. throw wirft einen eigenen Fehler.","code":"try {\n  JSON.parse('{kaputt');\n} catch (fehler) {\n  console.log(fehler.name);\n} finally {\n  console.log('fertig');\n}","out":"SyntaxError\nfertig","pitfall":"Fehler nicht stumm verschlucken. Entweder sinnvoll behandeln oder weiterwerfen. Immer Error-Objekte werfen, keine Strings.","lesson":"js-m1-l4","tested":true},{"id":"js-promise","cat":"Asynchron","term":"Promise","syntax":"new Promise((resolve, reject) => …)    .then(…).catch(…)","text":"Steht für ein Ergebnis, das erst später vorliegt. then verarbeitet den Erfolg, catch den Fehler. Ketten geben jeweils eine neue Promise zurück.","code":"Promise.resolve(2)\n  .then((n) => n * 5)\n  .then((n) => console.log(n))\n  .catch((e) => console.log('Fehler', e))\n  .finally(() => console.log('aus'));","out":"10\naus","pitfall":"Ohne return in einem then-Schritt geht der Wert verloren. Immer catch am Ende der Kette setzen.","lesson":"js-m1-l4","tested":true},{"id":"js-async-await","cat":"Asynchron","term":"async / await","syntax":"async function f() { const x = await promise; }","text":"async-Funktionen liefern immer eine Promise. await wartet in ihnen auf eine Promise, ohne den restlichen Code zu blockieren, und liest sich wie normaler Ablauf.","code":"const warte = (ms) => new Promise((r) => setTimeout(r, ms));\nasync function lade() {\n  await warte(10);\n  return 'geladen';\n}\nconsole.log(await lade());","out":"geladen","pitfall":"Unabhängige Aufgaben nicht nacheinander awaiten. Sie laufen mit Promise.all parallel. Fehler fängt man mit try/catch.","lesson":"js-m1-l4","tested":true},{"id":"js-promise-all","cat":"Asynchron","term":"Promise.all","syntax":"await Promise.all([p1, p2])","text":"Startet mehrere Promises gemeinsam und liefert ein Array aller Ergebnisse. Schlägt eine fehl, schlägt das Ganze fehl. Promise.allSettled meldet jedes Ergebnis einzeln.","code":"const [a, b] = await Promise.all([Promise.resolve(1), Promise.resolve(2)]);\nconsole.log(a + b);\nconst r = await Promise.allSettled([Promise.reject(new Error('x')), Promise.resolve(1)]);\nconsole.log(r.map((x) => x.status));","out":"3\n[ 'rejected', 'fulfilled' ]","pitfall":"Bei Promise.all gehen die Ergebnisse der übrigen verloren, sobald eine ablehnt. Wenn Teilergebnisse zählen, allSettled nehmen.","lesson":"js-m1-l4","tested":true},{"id":"js-fetch","cat":"Asynchron","term":"fetch","syntax":"const antwort = await fetch(url, optionen)","text":"Ruft eine URL ab und liefert eine Antwort. antwort.json() liest den Rumpf als JSON. Das Ergebnis immer auf antwort.ok prüfen.","code":"const antwort = await fetch('/api/aufgaben');\nif (!antwort.ok) throw new Error('HTTP ' + antwort.status);\nconst daten = await antwort.json();","pitfall":"fetch wirft bei HTTP 404 oder 500 keinen Fehler. Nur Netzwerkfehler werden zur Ausnahme. Immer ok oder status prüfen.","lesson":"js-m1-l5","tested":false},{"id":"js-import-export","cat":"Module","term":"import / export","syntax":"import { a } from './datei.js';    export const a = 1;","text":"Teilt Code in Dateien (ES-Module). export macht etwas verfügbar, import holt es. Mit export default gibt es genau einen Standardexport.","code":"// mathe.js\nexport const PI = 3.14;\nexport default function quadrat(x) { return x * x; }\n\n// app.js\nimport quadrat, { PI } from './mathe.js';","pitfall":"Im Browser braucht das Skript type=\"module\". Bei Node muss die Dateiendung .mjs sein oder package.json \"type\": \"module\" enthalten.","lesson":"js-m1-l4","tested":false},{"id":"js-dom-query","cat":"Browser (DOM)","term":"querySelector","syntax":"document.querySelector('.klasse')","text":"Liefert das erste Element, das zum CSS-Selektor passt, oder null. querySelectorAll liefert alle Treffer.","code":"const knopf = document.querySelector('#senden');\nknopf?.addEventListener('click', () => {\n  knopf.textContent = 'Gesendet';\n});","pitfall":"Gibt es keinen Treffer, ist das Ergebnis null. Vor dem Zugriff prüfen oder ?. verwenden. Nutzertexte mit textContent setzen, nicht mit innerHTML.","lesson":"js-m1-l5","tested":false},{"id":"js-events","cat":"Browser (DOM)","term":"addEventListener","syntax":"element.addEventListener('click', funktion)","text":"Meldet eine Funktion an, die bei einem Ereignis (click, input, submit, keydown …) aufgerufen wird. Die Funktion bekommt das Event-Objekt.","code":"formular.addEventListener('submit', (event) => {\n  event.preventDefault();\n  console.log(new FormData(formular).get('name'));\n});","pitfall":"Für Aktionen <button> nutzen, nicht <div>, damit Tastatur und Screenreader funktionieren. preventDefault verhindert das Neuladen bei submit.","lesson":"js-m1-l5","tested":false},{"id":"js-storage","cat":"Browser (DOM)","term":"localStorage","syntax":"localStorage.setItem('schluessel', 'text')","text":"Speichert Text dauerhaft im Browser, pro Website. sessionStorage gilt nur bis zum Schließen des Tabs.","code":"localStorage.setItem('theme', 'dunkel');\nconsole.log(localStorage.getItem('theme'));","pitfall":"Nur Text, daher JSON.stringify verwenden. Nichts Geheimes ablegen: jedes Skript der Seite kann es lesen. Zugriffe in try/catch setzen, der Zugriff kann blockiert sein.","lesson":"js-m1-l5","tested":false},{"id":"js-ts-types","cat":"TypeScript","term":"Typannotation","syntax":"let name: string;    function f(a: number): boolean","text":"Hängt einem Wert, Parameter oder Rückgabewert einen Typ an. Der Compiler meldet Verstöße schon vor dem Ausführen. Im Laufzeitcode bleibt nichts davon übrig.","code":"function verdopple(zahl: number): number {\n  return zahl * 2;\n}\nconst text: string = 'Hallo';\nconsole.log(verdopple(4), text);","out":"8 Hallo","pitfall":"Typen prüfen nur den Code, nicht Daten zur Laufzeit. Antworten einer API müssen zusätzlich validiert werden (z. B. mit Zod).","lesson":"js-m1-l7","tested":true},{"id":"js-ts-interface","cat":"TypeScript","term":"interface und type","syntax":"interface Name { feld: typ }    type Alias = …","text":"Beschreiben die Form eines Objekts. type kann zusätzlich Vereinigungen (\"a\" | \"b\") und Hilfskonstrukte ausdrücken. Ein ? macht ein Feld optional.","code":"interface Nutzer {\n  name: string;\n  alter?: number;\n}\ntype Rolle = 'admin' | 'gast';\nconst u: Nutzer = { name: 'Mia' };\nconst r: Rolle = 'gast';\nconsole.log(u.name, r);","out":"Mia gast","pitfall":"as-Umwandlungen (Type Assertions) schalten die Prüfung nur ab. Besser Typen eingrenzen oder die Daten validieren.","lesson":"js-m1-l7","tested":true},{"id":"js-ts-generics","cat":"TypeScript","term":"Generics","syntax":"function f<T>(wert: T): T","text":"Typparameter machen Funktionen und Typen für verschiedene Typen wiederverwendbar, ohne den Typ zu verlieren.","code":"function ersteres<T>(liste: T[]): T | undefined {\n  return liste[0];\n}\nconsole.log(ersteres<string>(['a', 'b']), ersteres([1, 2]));","out":"a 1","pitfall":"Mit noUncheckedIndexedAccess liefert liste[0] den Typ T | undefined. Das ist gewollt: der Fall „leer“ muss behandelt werden.","lesson":"js-m1-l7","tested":true},{"id":"js-ts-unknown","cat":"TypeScript","term":"unknown statt any","syntax":"const daten: unknown = …","text":"unknown nimmt jeden Wert an, erlaubt aber erst nach einer Prüfung (typeof, instanceof, Schema) die Verwendung. any schaltet die Typprüfung dagegen ab.","code":"function laenge(wert: unknown): number {\n  return typeof wert === 'string' ? wert.length : 0;\n}\nconsole.log(laenge('Haus'), laenge(42));","out":"4 0","pitfall":"any breitet sich aus: einmal verwendet, verliert alles, was davon abhängt, seine Prüfung.","lesson":"js-m1-l7","tested":true}]},{"id":"vue","label":"Vue 3","codeLang":"vue","intro":"Framework für Oberflächen. Komponenten stehen in .vue-Dateien (Template, Skript, Stil). Hier die Schreibweise mit <script setup> und der Composition API.","notice":"Diese Beispiele werden hier nicht ausgeführt. Sie folgen Vue 3.5 mit <script setup>; die vollständigen, getesteten Beispielprojekte liegen in den Labs der Lektionen.","runner":"","entries":[{"id":"vue-sfc","cat":"Komponente","term":"Single-File-Component","syntax":"<script setup lang=\"ts\">…</script>\n<template>…</template>\n<style scoped>…</style>","text":"Eine .vue-Datei enthält Logik, Template und Stil. Alles Deklarierte in <script setup> ist im Template direkt verfügbar. scoped begrenzt den Stil auf diese Komponente.","code":"<script setup lang=\"ts\">\nimport { ref } from 'vue'\nconst name = ref('Ada')\n</script>\n\n<template>\n  <p>Hallo {{ name }}</p>\n</template>","pitfall":"In <script setup> gibt es kein this. Zustand und Funktionen sind einfache Variablen.","lesson":"js-m1-l8","tested":false},{"id":"vue-ref","cat":"Reaktivität","term":"ref","syntax":"const zahl = ref(0)    zahl.value","text":"Macht einen Wert reaktiv. Im Skript greift man über .value zu, im Template wird .value automatisch ergänzt.","code":"const zaehler = ref(0)\nfunction erhoehe() {\n  zaehler.value++\n}","pitfall":"Das Vergessen von .value im Skript ist der häufigste Anfängerfehler. zaehler++ ändert nichts Reaktives.","lesson":"js-m1-l9","tested":false},{"id":"vue-reactive","cat":"Reaktivität","term":"reactive","syntax":"const zustand = reactive({ a: 1 })","text":"Macht ein Objekt reaktiv, der Zugriff erfolgt ohne .value. Es funktioniert nur für Objekte und verliert die Reaktivität, wenn man Eigenschaften einzeln herauslöst.","code":"const form = reactive({ name: '', mail: '' })\nconst { name } = form   // verliert die Reaktivität!\nconst nameRef = toRef(form, 'name')   // bleibt reaktiv","pitfall":"Destructuring von reactive-Objekten und Props trennt die Verbindung. Dafür toRef, toRefs oder storeToRefs (Pinia) verwenden.","lesson":"js-m4-l4","tested":false},{"id":"vue-computed","cat":"Reaktivität","term":"computed","syntax":"const x = computed(() => …)","text":"Berechneter Wert, der sich nur neu berechnet, wenn sich seine Abhängigkeiten ändern. Er ist gedacht für abgeleitete Daten ohne Nebenwirkungen.","code":"const preis = ref(10)\nconst menge = ref(3)\nconst summe = computed(() => preis.value * menge.value)","pitfall":"In computed keine Daten ändern und keine Anfragen senden. Für Reaktionen auf Änderungen gibt es watch.","lesson":"js-m1-l9","tested":false},{"id":"vue-watch","cat":"Reaktivität","term":"watch und watchEffect","syntax":"watch(quelle, (neu, alt) => …)","text":"watch führt eine Funktion aus, wenn sich eine Quelle ändert, etwa um zu laden oder zu speichern. watchEffect läuft sofort und verfolgt automatisch alle benutzten Werte.","code":"watch(suche, async (neu, alt, onCleanup) => {\n  const abbruch = new AbortController()\n  onCleanup(() => abbruch.abort())\n  ergebnisse.value = await lade(neu, abbruch.signal)\n})","pitfall":"Schnell aufeinanderfolgende Änderungen starten mehrere Anfragen. onCleanup bricht die alte ab, sonst gewinnt eine zufällig langsame Antwort.","lesson":"js-m1-l9","tested":false},{"id":"vue-interpolation","cat":"Template","term":"{{ }} und v-bind","syntax":"{{ ausdruck }}    :attribut=\"ausdruck\"","text":"{{ }} setzt Text ein (automatisch maskiert), :attribut (Kurzform von v-bind) bindet ein Attribut an einen Ausdruck.","code":"<img :src=\"bild.url\" :alt=\"bild.beschreibung\">\n<button :disabled=\"laeuft\">{{ laeuft ? 'Lädt …' : 'Speichern' }}</button>","pitfall":"v-html fügt rohes HTML ein und öffnet XSS-Lücken. Nur mit bereinigtem eigenem Inhalt benutzen, niemals mit Nutzertext.","lesson":"js-m1-l8","tested":false},{"id":"vue-if","cat":"Template","term":"v-if, v-else, v-show","syntax":"<p v-if=\"bedingung\">…</p><p v-else>…</p>","text":"v-if erzeugt das Element nur, wenn die Bedingung wahr ist. v-show blendet es lediglich per CSS ein und aus. Für häufiges Umschalten ist v-show günstiger.","code":"<p v-if=\"laedt\">Lade …</p>\n<p v-else-if=\"fehler\" role=\"alert\">{{ fehler }}</p>\n<ul v-else>…</ul>","pitfall":"Zuerst Lade- und Fehlerzustand behandeln, erst dann die Daten zeigen. Sonst blitzen leere oder alte Inhalte auf.","lesson":"js-m1-l8","tested":false},{"id":"vue-for","cat":"Template","term":"v-for und :key","syntax":"<li v-for=\"x in liste\" :key=\"x.id\">","text":"Wiederholt ein Element für jedes Listenelement. :key muss eindeutig und stabil sein (eine ID), damit Vue Elemente beim Verändern der Liste richtig zuordnet.","code":"<li v-for=\"aufgabe in aufgaben\" :key=\"aufgabe.id\">\n  {{ aufgabe.titel }}\n</li>","pitfall":"Den Listenindex als :key zu verwenden bringt bei Einfügen, Löschen oder Umsortieren falsche Zuordnung von Zustand und Fokus. IDs verwenden.","lesson":"js-m4-l5","tested":false},{"id":"vue-on","cat":"Template","term":"@click und Modifikatoren","syntax":"@click=\"funktion\"    @submit.prevent=\"senden\"","text":"@ ist die Kurzform von v-on und hängt Ereignisse an. Modifikatoren wie .prevent, .stop oder .enter (bei Tasten) vereinfachen die Behandlung.","code":"<form @submit.prevent=\"speichern\">\n  <input v-model.trim=\"name\">\n  <button type=\"submit\">Speichern</button>\n</form>","pitfall":"Auch in Vue gilt: Für klickbare Dinge <button> oder <a> verwenden, kein <div @click>, damit die Tastatur funktioniert.","lesson":"js-m1-l8","tested":false},{"id":"vue-model","cat":"Template","term":"v-model","syntax":"<input v-model=\"text\">","text":"Zweiwegebindung für Formularfelder: Der Wert fließt ins Feld, Eingaben zurück in die Variable. Modifikatoren: .trim, .number, .lazy.","code":"<label for=\"mail\">E-Mail</label>\n<input id=\"mail\" type=\"email\" v-model.trim=\"mail\">\n<p>{{ mail }}</p>","pitfall":"v-model.number liefert bei leerem oder ungültigem Feld wieder den Text zurück. Zahlen zusätzlich prüfen.","lesson":"js-m1-l10","tested":false},{"id":"vue-props","cat":"Komponenten","term":"defineProps","syntax":"const props = defineProps<{ titel: string }>()","text":"Deklariert, welche Eingaben eine Komponente von außen bekommt. Props fließen nur nach unten und werden in der Kindkomponente nicht verändert.","code":"const props = withDefaults(defineProps<{ titel: string; offen?: boolean }>(), {\n  offen: false,\n})","pitfall":"Props nicht direkt ändern. Stattdessen ein Ereignis (emit) senden oder defineModel nutzen.","lesson":"js-m1-l10","tested":false},{"id":"vue-emits","cat":"Komponenten","term":"defineEmits","syntax":"const emit = defineEmits<{ speichern: [name: string] }>()","text":"Deklariert die Ereignisse, die eine Komponente nach oben meldet. Der Elternteil hört mit @speichern=\"…\" zu.","code":"const emit = defineEmits<{ speichern: [name: string] }>()\nfunction fertig() {\n  emit('speichern', name.value)\n}","pitfall":"Ereignisnamen sind kein Ersatz für Daten. Sie melden, dass etwas passiert ist, und liefern nur die nötige Nutzlast mit.","lesson":"js-m1-l10","tested":false},{"id":"vue-definemodel","cat":"Komponenten","term":"defineModel","syntax":"const wert = defineModel<string>()","text":"Macht aus einer Komponente ein v-model-fähiges Feld. Die Variable verhält sich wie ein ref, Änderungen fließen automatisch zum Elternteil.","code":"<script setup lang=\"ts\">\nconst text = defineModel<string>({ required: true })\n</script>\n\n<template>\n  <input v-model=\"text\">\n</template>","pitfall":"Erfordert Vue 3.4 oder neuer. Für mehrere Werte benannte Modelle verwenden: defineModel('titel').","lesson":"js-m2-l1","tested":false},{"id":"vue-slots","cat":"Komponenten","term":"Slots","syntax":"<slot />    <template #name=\"props\">","text":"Slots reichen Inhalt von außen in eine Komponente hinein. Benannte Slots (#kopf) legen Bereiche fest, Scoped Slots geben Daten an den Aufrufer zurück.","code":"<!-- Karte.vue -->\n<section>\n  <header><slot name=\"kopf\" /></header>\n  <slot />\n</section>\n\n<!-- Verwendung -->\n<Karte>\n  <template #kopf>Titel</template>\n  Inhalt\n</Karte>","pitfall":"Slot-Inhalt gehört zum Elternteil und sieht nur dessen Variablen, nicht die der Komponente, außer sie werden als Scoped-Slot-Daten übergeben.","lesson":"js-m2-l3","tested":false},{"id":"vue-provide","cat":"Komponenten","term":"provide und inject","syntax":"provide('schluessel', wert)    const x = inject('schluessel')","text":"Reicht Werte über beliebig viele Ebenen nach unten, ohne sie als Props durchzureichen. Mit einem InjectionKey bleibt die Typisierung erhalten.","code":"// Eltern\nprovide(themeKey, theme)\n\n// beliebige Nachkommen\nconst theme = inject(themeKey)\nif (!theme) throw new Error('Theme-Provider fehlt')","pitfall":"inject liefert undefined, wenn kein provide existiert. Das fehlende Szenario ausdrücklich behandeln oder einen Fehler werfen.","lesson":"js-m2-l2","tested":false},{"id":"vue-lifecycle","cat":"Reaktivität","term":"onMounted und onUnmounted","syntax":"onMounted(() => …)","text":"Hooks, die in bestimmten Phasen der Komponente laufen: onMounted nach dem Einfügen in die Seite, onUnmounted vor dem Entfernen. Dort räumt man Timer, Listener und Abonnements auf.","code":"onMounted(() => {\n  window.addEventListener('resize', messen)\n})\nonUnmounted(() => {\n  window.removeEventListener('resize', messen)\n})","pitfall":"Nicht aufgeräumte Listener und Timer sammeln sich bei jedem Öffnen der Komponente an (Speicherleck).","lesson":"js-m1-l9","tested":false},{"id":"vue-composable","cat":"Struktur","term":"Composable","syntax":"function useXyz() { … return { … } }","text":"Eine Funktion mit Namen use…, die reaktiven Zustand und Logik bündelt und wiederverwendbar macht, zum Beispiel für Ladezustände einer API.","code":"export function useAufgaben() {\n  const daten = ref<Aufgabe[]>([])\n  const fehler = ref<string | null>(null)\n  const laedt = ref(false)\n  async function laden() { /* … */ }\n  return { daten, fehler, laedt, laden }\n}","pitfall":"Composables nur synchron im setup-Bereich aufrufen. Ein Aufruf nach einem await oder in einer Schleife verliert den Komponentenbezug.","lesson":"js-m1-l11","tested":false},{"id":"vue-router","cat":"Router und Pinia","term":"RouterLink und useRoute","syntax":"<RouterLink to=\"/pfad\">    const route = useRoute()","text":"RouterLink ist der Link innerhalb der App, ohne vollständiges Neuladen. useRoute liest Pfad, Parameter und Query, useRouter navigiert per Code.","code":"const route = useRoute()\nconst router = useRouter()\nconst id = computed(() => String(route.params.id))\nfunction zurueck() { router.push({ name: 'liste' }) }","pitfall":"Route-Parameter sind Text. Zahlen müssen umgewandelt und geprüft werden, und das Ganze am besten in computed, damit es bei Routenwechsel neu berechnet wird.","lesson":"js-m1-l12","tested":false},{"id":"vue-guard","cat":"Router und Pinia","term":"Navigation Guard","syntax":"router.beforeEach((to, from) => …)","text":"Läuft vor jedem Seitenwechsel. Man kann false oder einen Zielpfad zurückgeben, um die Navigation abzubrechen oder umzuleiten, etwa zur Anmeldung.","code":"router.beforeEach((to) => {\n  const auth = useAuthStore()\n  if (to.meta.requiresAuth && !auth.eingeloggt) {\n    return { name: 'login', query: { weiter: to.fullPath } }\n  }\n})","pitfall":"Ein Guard schützt nur die Oberfläche. Zugriff auf Daten muss der Server selbst prüfen.","lesson":"js-m4-l1","tested":false},{"id":"vue-pinia","cat":"Router und Pinia","term":"Pinia-Store","syntax":"export const useXStore = defineStore('x', () => { … })","text":"Gemeinsamer Zustand über Komponenten hinweg. Im Setup-Stil sind ref-Werte der State, computed-Werte die Getter und Funktionen die Aktionen.","code":"export const useZaehlerStore = defineStore('zaehler', () => {\n  const stand = ref(0)\n  const doppelt = computed(() => stand.value * 2)\n  function erhoehe() { stand.value++ }\n  return { stand, doppelt, erhoehe }\n})\n\n// in der Komponente\nconst store = useZaehlerStore()\nconst { stand } = storeToRefs(store)","pitfall":"Wer State oder Getter mit const { stand } = store herauslöst, verliert die Reaktivität. Dafür storeToRefs nehmen; Aktionen dürfen direkt vom Store kommen.","lesson":"js-m1-l13","tested":false},{"id":"vue-templateref","cat":"Komponenten","term":"useTemplateRef und useId","syntax":"const el = useTemplateRef('name')    const id = useId()","text":"useTemplateRef greift auf ein DOM-Element zu (z. B. für Fokus). useId erzeugt stabile eindeutige IDs für Label und Eingabefeld, auch bei Server-Rendering.","code":"<script setup lang=\"ts\">\nconst feld = useTemplateRef<HTMLInputElement>('feld')\nconst id = useId()\nonMounted(() => feld.value?.focus())\n</script>\n\n<template>\n  <label :for=\"id\">Name</label>\n  <input :id=\"id\" ref=\"feld\">\n</template>","pitfall":"Beide Funktionen sind ab Vue 3.5 verfügbar. Das Element ist erst nach dem Einfügen vorhanden, davor ist feld.value null.","lesson":"js-m4-l3","tested":false},{"id":"vue-zod","cat":"Daten","term":"Zod-Schema","syntax":"const Schema = z.object({ … })    Schema.safeParse(daten)","text":"Beschreibt die erwartete Form von Daten und prüft sie zur Laufzeit. Aus demselben Schema entsteht der TypeScript-Typ. safeParse liefert ein Ergebnisobjekt statt einer Ausnahme.","code":"const Nutzer = z.object({ name: z.string().min(2), alter: z.number().int().min(0) })\ntype Nutzer = z.infer<typeof Nutzer>\n\nconst ergebnis = Nutzer.safeParse(daten)\nif (!ergebnis.success) {\n  console.log(ergebnis.error.issues)\n}","pitfall":"Zod prüft die Struktur, nicht die Berechtigung. Daten vom Server sollten trotzdem am Server validiert werden.","lesson":"js-m3-l1","tested":false},{"id":"vue-query","cat":"Daten","term":"useQuery (TanStack Query)","syntax":"useQuery({ queryKey: [...], queryFn: … })","text":"Lädt Serverdaten, speichert sie in einem Cache und liefert reaktiv data, error und isPending. Der queryKey identifiziert die Daten, bei Änderung wird neu geladen.","code":"const { data, error, isPending } = useQuery({\n  queryKey: ['aufgaben', seite],\n  queryFn: () => ladeAufgaben(seite.value),\n})","pitfall":"Alle Werte, von denen die Anfrage abhängt, gehören in den queryKey. Sonst zeigt der Cache falsche Daten.","lesson":"js-m3-l2","tested":false}]},{"id":"php","label":"PHP","codeLang":"php","intro":"Serverseitige Sprache für Webanwendungen. Variablen beginnen mit $, Anweisungen enden mit Semikolon.","notice":"Die meisten Beispiele sind mit PHP 8.5 ausgeführt und geprüft. Beispiele ohne Markierung (z. B. Namespaces) werden nur gezeigt.","runner":"PHP","entries":[{"id":"php-tag","cat":"Grundlagen","term":"<?php … ?>","syntax":"<?php\ndeclare(strict_types=1);","text":"Der PHP-Block beginnt mit <?php. In reinen PHP-Dateien wird das schließende ?> weggelassen. declare(strict_types=1) macht die Typprüfung bei Funktionsaufrufen streng.","code":"declare(strict_types=1);\necho 'läuft', PHP_EOL;","out":"läuft","pitfall":"Ein ?> am Dateiende mit Leerzeichen oder Zeilenumbruch dahinter erzeugt unerwünschte Ausgabe, bevor Header gesendet werden.","lesson":"m52-l1","tested":true},{"id":"php-echo","cat":"Grundlagen","term":"echo und print_r / var_dump","syntax":"echo $text;    var_dump($wert);","text":"echo gibt Text aus. var_dump zeigt Typ und Wert, print_r ist die lesbare Kurzform für Arrays. Beide dienen dem Debuggen.","code":"$a = ['x' => 1];\necho 'Wert: ', $a['x'], PHP_EOL;\nvar_dump(1.5, 'a', true);","out":"Wert: 1\nfloat(1.5)\nstring(1) \"a\"\nbool(true)","pitfall":"Ausgaben aus dem Browser immer mit htmlspecialchars() maskieren, sonst droht Cross-Site-Scripting.","lesson":"m52-l2","tested":true},{"id":"php-variable","cat":"Variablen und Typen","term":"Variable","syntax":"$name = wert;","text":"Variablen beginnen mit $ und brauchen keine Typdeklaration. Groß- und Kleinschreibung zählt. Konstanten legt man mit const oder define an.","code":"$preis = 19.99;\nconst STEUER = 0.19;\necho round($preis * (1 + STEUER), 2), PHP_EOL;","out":"23.79","pitfall":"Eine nicht gesetzte Variable erzeugt eine Warnung. Vorher mit isset() prüfen oder einen Standardwert verwenden.","lesson":"m42-l2","tested":true},{"id":"php-types","cat":"Variablen und Typen","term":"Typen und Vergleiche","syntax":"$a === $b    $a == $b","text":"Skalare Typen sind int, float, string und bool. === vergleicht Wert und Typ, == wandelt vorher um und liefert dadurch Überraschungen.","code":"var_dump(0 == 'a', '1' == '01', '10' == '1e1', 100 == '1e2', 1 === '1');","out":"bool(false)\nbool(true)\nbool(true)\nbool(true)\nbool(false)","pitfall":"Immer === verwenden. Auch seit PHP 8 sind „1“ == „01“ und „10“ == „1e1“ wahr, weil numerische Strings als Zahlen verglichen werden.","lesson":"m42-l2","tested":true},{"id":"php-string","cat":"Strings","term":"Strings und Verkettung","syntax":"'einfach'    \"doppelt $variable\"    $a . $b","text":"In einfachen Anführungszeichen steht der Text wörtlich, in doppelten werden Variablen eingesetzt. Der Punkt verkettet Strings.","code":"$name = 'Ada';\necho \"Hallo $name\", PHP_EOL;\necho 'Hallo ' . $name . '!', PHP_EOL;\necho strlen('Haus'), ' ', strtoupper('abc'), ' ', str_contains('Werkstatt', 'stat') ? 'ja' : 'nein', PHP_EOL;","out":"Hallo Ada\nHallo Ada!\n4 ABC ja","pitfall":"strlen zählt Bytes. Bei Umlauten liefert mb_strlen() die Anzahl der Zeichen.","lesson":"m52-l2","tested":true},{"id":"php-if","cat":"Kontrollfluss","term":"if / elseif / else","syntax":"if (bedingung) { … } elseif (…) { … } else { … }","text":"Führt einen Block nur aus, wenn die Bedingung wahr ist. Falsch sind false, 0, \"\", \"0\", null und leere Arrays.","code":"$punkte = 72;\nif ($punkte >= 90) {\n    echo 'sehr gut';\n} elseif ($punkte >= 70) {\n    echo 'gut';\n} else {\n    echo 'weiter üben';\n}","out":"gut","pitfall":"Die Zeichenkette \"0\" gilt als falsch. Bei Formulareingaben deshalb nicht nur if ($wert) prüfen, sondern gezielt auf null und \"\".","lesson":"m52-l4","tested":true},{"id":"php-match","cat":"Kontrollfluss","term":"match","syntax":"match ($wert) { a => x, b, c => y, default => z }","text":"Wie switch, aber als Ausdruck mit Rückgabewert, strengem Vergleich und ohne Durchfallen. Wird kein Fall getroffen und gibt es kein default, wirft PHP einen UnhandledMatchError.","code":"$status = 404;\n$text = match ($status) {\n    200 => 'OK',\n    404, 410 => 'Nicht gefunden',\n    default => 'Unbekannt',\n};\necho $text;","out":"Nicht gefunden","pitfall":"match vergleicht strikt: die Zahl 404 passt nicht auf den Text \"404\".","lesson":"m52-l4","tested":true},{"id":"php-ternary","cat":"Kontrollfluss","term":"?: und ??","syntax":"$a ?: $b    $a ?? $b","text":"?? liefert den rechten Wert, wenn links null ist oder nicht existiert, ohne Warnung. ?: nimmt den rechten Wert, wenn links falsch ist.","code":"$eingabe = ['name' => ''];\necho $eingabe['alter'] ?? 'unbekannt', PHP_EOL;\necho $eingabe['name'] ?: 'ohne Namen', PHP_EOL;","out":"unbekannt\nohne Namen","pitfall":"?? ist die richtige Wahl für „Schlüssel fehlt“, ?: für „leer oder falsy“. Beides nicht verwechseln.","lesson":"m52-l4","tested":true},{"id":"php-foreach","cat":"Schleifen","term":"foreach","syntax":"foreach ($liste as $schluessel => $wert) { … }","text":"Läuft über alle Elemente eines Arrays. Mit $schluessel => $wert steht auch der Schlüssel zur Verfügung.","code":"foreach (['a' => 1, 'b' => 2] as $k => $v) {\n    echo \"$k=$v \";\n}","out":"a=1 b=2","pitfall":"Mit foreach ($liste as &$x) bleibt $x nach der Schleife eine Referenz auf das letzte Element. Danach unset($x) aufrufen.","lesson":"m52-l5","tested":true},{"id":"php-for-while","cat":"Schleifen","term":"for und while","syntax":"for ($i = 0; $i < $n; $i++) { … }    while (bedingung) { … }","text":"for ist die Zählschleife, while läuft, solange die Bedingung gilt. break beendet, continue springt zum nächsten Durchlauf.","code":"for ($i = 1; $i <= 3; $i++) {\n    if ($i === 2) continue;\n    echo $i;\n}\n$n = 3;\nwhile ($n > 0) { echo $n--; }","out":"13321","pitfall":"Eine while-Schleife ohne Änderung der Bedingung läuft endlos. Im Zweifel einen Zähler als Sicherung mitführen.","lesson":"m52-l5","tested":true},{"id":"php-array","cat":"Arrays","term":"Array","syntax":"$liste = [1, 2];    $karte = ['schluessel' => 'wert'];","text":"Ein Array ist in PHP Liste und Wörterbuch zugleich. Mit [] wird angehängt, mit isset() prüft man, ob ein Schlüssel existiert, mit count() zählt man.","code":"$a = ['x' => 1];\n$a['y'] = 2;\n$liste = [10, 20];\n$liste[] = 30;\necho count($a), ' ', count($liste), ' ', isset($a['z']) ? 'ja' : 'nein';","out":"2 3 nein","pitfall":"Ein Zugriff auf einen fehlenden Schlüssel erzeugt eine Warnung und liefert null. Mit ?? einen Standardwert vorgeben.","lesson":"m53-l1","tested":true},{"id":"php-array-functions","cat":"Arrays","term":"array_map, array_filter, usort","syntax":"array_map(fn, $liste)    array_filter($liste, fn)    usort($liste, fn)","text":"array_map wandelt jedes Element um, array_filter behält passende (die Schlüssel bleiben erhalten), usort sortiert mit eigener Vergleichsfunktion. Mit <=> wird zahlenmäßig verglichen.","code":"$z = [5, 12, 8];\necho implode(',', array_map(fn ($n) => $n * 2, $z)), PHP_EOL;\necho implode(',', array_filter($z, fn ($n) => $n > 6)), PHP_EOL;\nusort($z, fn ($a, $b) => $b <=> $a);\necho implode(',', $z);","out":"10,24,16\n12,8\n12,8,5","pitfall":"array_filter erhält die ursprünglichen Schlüssel. Mit array_values() die Liste neu durchnummerieren.","lesson":"m53-l2","tested":true},{"id":"php-destructuring","cat":"Arrays","term":"Spread und Destructuring","syntax":"[$a, $b] = $liste;    [...$a, ...$b]","text":"Mit [$a, $b] = … werden Elemente in Variablen verteilt, mit ... werden Arrays zusammengefügt oder als Argumente entpackt.","code":"[$x, $y] = [1, 2];\n['name' => $n] = ['name' => 'Ada'];\n$alle = [...[1, 2], ...[3]];\necho \"$x $y $n \", count($alle);","out":"1 2 Ada 3","pitfall":"Mit String-Schlüsseln im Spread braucht man PHP 8.1 oder neuer. Bei doppelten Schlüsseln gewinnt der spätere.","lesson":"m53-l1","tested":true},{"id":"php-function","cat":"Funktionen","term":"function mit Typen","syntax":"function name(int $a, ?string $b = null): string { … }","text":"Parameter und Rückgabewert können Typen tragen. ?string heißt „string oder null“, void bedeutet „liefert nichts“. Benannte Argumente (name: wert) machen Aufrufe lesbar.","code":"function gruss(string $name, string $anrede = 'Hallo'): string\n{\n    return \"$anrede $name\";\n}\necho gruss(anrede: 'Moin', name: 'Ada');","out":"Moin Ada","pitfall":"Ohne declare(strict_types=1) wandelt PHP Typen still um, aus \"5\" wird 5. Mit strict_types wirft es stattdessen einen TypeError.","lesson":"m42-l4","tested":true},{"id":"php-arrow","cat":"Funktionen","term":"Pfeilfunktion und Closure","syntax":"fn ($x) => $x * 2    function ($x) use ($y) { … }","text":"Pfeilfunktionen übernehmen Variablen aus der Umgebung automatisch (nur lesend). Klassische Closures holen sie mit use. use (&$x) gibt Schreibzugriff.","code":"$faktor = 3;\n$mal = fn ($x) => $x * $faktor;\n$zaehler = 0;\n$erhoehe = function () use (&$zaehler) { $zaehler++; };\n$erhoehe();\necho $mal(4), ' ', $zaehler;","out":"12 1","pitfall":"In Pfeilfunktionen ändert eine Zuweisung die äußere Variable nicht, sie arbeitet auf einer Kopie.","lesson":"m42-l4","tested":true},{"id":"php-class","cat":"Klassen","term":"class mit Konstruktor-Promotion","syntax":"class Name { public function __construct(private readonly int $x) {} }","text":"Parameter mit Sichtbarkeit im Konstruktor werden gleich zu Eigenschaften (Promotion). readonly erlaubt nur eine einmalige Zuweisung. new erzeugt ein Objekt.","code":"final class Punkt\n{\n    public function __construct(\n        public readonly int $x,\n        public readonly int $y = 0,\n    ) {}\n\n    public function summe(): int\n    {\n        return $this->x + $this->y;\n    }\n}\n$p = new Punkt(2, 3);\necho $p->summe();","out":"5","pitfall":"readonly-Eigenschaften lassen sich nicht ändern. Für Änderungen ein neues Objekt erzeugen (withX()-Methoden).","lesson":"m44-l1","tested":true},{"id":"php-interface","cat":"Klassen","term":"interface, abstract, trait","syntax":"interface Name { … }    abstract class …    trait Name { … }","text":"Ein Interface legt Methoden fest, die Klassen anbieten müssen. Abstrakte Klassen teilen Code und erzwingen Methoden. Traits fügen wiederverwendbaren Code in mehrere Klassen ein.","code":"interface Formatierer { public function format(string $s): string; }\ntrait Protokoll { public function log(string $s): string { return '[log] ' . $s; } }\nfinal class Gross implements Formatierer\n{\n    use Protokoll;\n    public function format(string $s): string { return strtoupper($s); }\n}\n$g = new Gross();\necho $g->log($g->format('ok'));","out":"[log] OK","pitfall":"Traits sind keine Vererbung, sondern Codekopie zur Laufzeit. Zu viele Traits verstecken Abhängigkeiten. Oft ist ein Interface plus Objekt die klarere Lösung.","lesson":"m44-l2","tested":true},{"id":"php-enum","cat":"Klassen","term":"enum","syntax":"enum Status: string { case Offen = 'offen'; }","text":"Ein Enum beschreibt eine feste Menge erlaubter Werte. Ein „backed enum“ hat zusätzlich einen Text oder eine Zahl pro Fall. from() liest, tryFrom() liefert bei Unbekanntem null.","code":"enum Status: string\n{\n    case Offen = 'offen';\n    case Fertig = 'fertig';\n\n    public function label(): string\n    {\n        return ucfirst($this->value);\n    }\n}\necho Status::from('fertig')->label(), ' ', var_export(Status::tryFrom('x'), true);","out":"Fertig NULL","pitfall":"Status::from() wirft bei unbekanntem Wert einen ValueError. Eingaben von außen mit tryFrom() prüfen.","lesson":"m44-l3","tested":true},{"id":"php-exception","cat":"Fehler","term":"try / catch / throw","syntax":"try { … } catch (Typ $e) { … } finally { … }","text":"Fängt Ausnahmen. Mehrere Typen lassen sich mit | kombinieren. throw wirft eine neue Ausnahme, das Original kann als previous mitgegeben werden.","code":"try {\n    intdiv(1, 0);\n} catch (DivisionByZeroError $e) {\n    echo get_class($e), ': ', $e->getMessage();\n}","out":"DivisionByZeroError: Division by zero","pitfall":"Error und Exception sind getrennte Zweige. catch (Exception) fängt keinen TypeError. Mit Throwable fängt man beide.","lesson":"m44-l3","tested":true},{"id":"php-namespace","cat":"Klassen","term":"namespace und use","syntax":"namespace App\\Modelle;    use App\\Modelle\\Nutzer;","text":"Namensräume verhindern Namenskollisionen und folgen meist der Ordnerstruktur (PSR-4). use importiert eine Klasse unter ihrem kurzen Namen.","code":"namespace App\\Modelle;\n\nuse DateTimeImmutable;\n\nfinal class Nutzer\n{\n    public function __construct(public DateTimeImmutable $erstellt) {}\n}","pitfall":"Globale Klassen wie DateTimeImmutable brauchen im Namensraum ein führendes \\ oder ein use, sonst sucht PHP sie im aktuellen Namensraum.","lesson":"m44-l4","tested":false},{"id":"php-form","cat":"Web","term":"$_POST, $_GET und htmlspecialchars","syntax":"$_POST['feld']    htmlspecialchars($text, ENT_QUOTES)","text":"Superglobals enthalten die Daten der Anfrage. Sie sind Nutzereingaben und müssen geprüft werden. Vor der Ausgabe in HTML mit htmlspecialchars maskieren.","code":"$eingabe = '<script>alert(1)</script>';\necho htmlspecialchars($eingabe, ENT_QUOTES);","out":"&lt;script&gt;alert(1)&lt;/script&gt;","pitfall":"Validieren (stimmt das Format?) und maskieren (sichere Ausgabe) sind zwei getrennte Schritte. Keiner ersetzt den anderen.","lesson":"m43-l1","tested":true},{"id":"php-pdo","cat":"Web","term":"PDO mit Prepared Statements","syntax":"$stmt = $pdo->prepare('… WHERE id = :id');\n$stmt->execute(['id' => $id]);","text":"Prepared Statements trennen SQL und Daten. Platzhalter (:name oder ?) werden vom Treiber sicher eingesetzt. So ist SQL-Injection ausgeschlossen.","code":"$pdo = new PDO('sqlite::memory:', options: [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);\n$pdo->exec('CREATE TABLE nutzer (id INTEGER PRIMARY KEY, name TEXT)');\n$pdo->prepare('INSERT INTO nutzer (name) VALUES (:name)')->execute(['name' => \"O'Brien\"]);\n$stmt = $pdo->prepare('SELECT name FROM nutzer WHERE id = :id');\n$stmt->execute(['id' => 1]);\necho $stmt->fetchColumn();","out":"O'Brien","pitfall":"Tabellen- oder Spaltennamen lassen sich nicht als Parameter binden. Dafür eine feste Liste erlaubter Namen verwenden.","lesson":"m43-l3","tested":true},{"id":"php-json","cat":"Dateien und Daten","term":"json_encode und json_decode","syntax":"json_encode($daten)    json_decode($text, true, flags: JSON_THROW_ON_ERROR)","text":"Wandelt PHP-Daten in JSON-Text und zurück. Mit true als zweitem Argument entstehen Arrays statt Objekte. JSON_THROW_ON_ERROR wirft bei ungültigem JSON eine Ausnahme.","code":"$text = json_encode(['a' => 1, 'b' => [true, null]]);\necho $text, PHP_EOL;\ntry {\n    json_decode('{kaputt', true, flags: JSON_THROW_ON_ERROR);\n} catch (JsonException $e) {\n    echo 'ungültig';\n}","out":"{\"a\":1,\"b\":[true,null]}\nungültig","pitfall":"Ohne JSON_THROW_ON_ERROR liefert json_decode bei Fehlern stillschweigend null. Dann ist nicht klar, ob der Text „null“ oder kaputt war.","lesson":"m54-l2","tested":true},{"id":"php-datetime","cat":"Dateien und Daten","term":"DateTimeImmutable","syntax":"new DateTimeImmutable('2026-01-31')    ->modify('+1 day')    ->format('d.m.Y')","text":"Unveränderliches Datumsobjekt: jede Änderung liefert ein neues Objekt. Mit format() wird die Darstellung gewählt.","code":"$d = new DateTimeImmutable('2026-01-31', new DateTimeZone('Europe/Berlin'));\n$naechster = $d->modify('+1 day');\necho $d->format('d.m.Y'), ' ', $naechster->format('d.m.Y');","out":"31.01.2026 01.02.2026","pitfall":"Das veränderliche DateTime ändert sich beim Aufruf von modify() selbst. Das führt zu schwer findbaren Fehlern, deshalb DateTimeImmutable verwenden.","lesson":"m53-l4","tested":true},{"id":"php-file","cat":"Dateien und Daten","term":"file_put_contents und file_get_contents","syntax":"file_put_contents($pfad, $text, LOCK_EX)    file_get_contents($pfad)","text":"Schreibt und liest ganze Dateien. LOCK_EX sperrt die Datei beim Schreiben. Bei Fehlern liefern beide false statt einer Ausnahme.","code":"$pfad = sys_get_temp_dir() . '/glossar-test.txt';\nfile_put_contents($pfad, \"Zeile 1\\n\", LOCK_EX);\necho trim(file_get_contents($pfad));\nunlink($pfad);","out":"Zeile 1","pitfall":"Dateipfade aus Nutzereingaben nie direkt verwenden (Path Traversal). Mit basename() und einer festen Zielordner arbeiten.","lesson":"m54-l1","tested":true},{"id":"php-generator","cat":"Funktionen","term":"Generator (yield)","syntax":"function zahlen() { yield 1; yield 2; }","text":"Eine Funktion mit yield liefert die Werte nacheinander, statt eine ganze Liste aufzubauen. Das spart Speicher bei großen Datenmengen.","code":"function bis(int $n): Generator\n{\n    for ($i = 1; $i <= $n; $i++) {\n        yield $i;\n    }\n}\nforeach (bis(3) as $z) { echo $z; }","out":"123","pitfall":"Ein Generator lässt sich nur einmal durchlaufen. Ein zweites foreach darüber wirft eine Ausnahme.","lesson":"m55-l1","tested":true},{"id":"php-nullsafe","cat":"Variablen und Typen","term":"?-> (Nullsafe)","syntax":"$objekt?->methode()?->eigenschaft","text":"Bricht die Kette ab und liefert null, sobald ein Zwischenwert null ist, statt einen Fehler zu werfen.","code":"$nutzer = null;\nvar_dump($nutzer?->adresse?->ort);","out":"NULL","pitfall":"Das Ergebnis kann null sein. Wer den Wert weiterverwendet, muss diesen Fall behandeln.","lesson":"m42-l4","tested":true}]},{"id":"laravel","label":"Laravel","codeLang":"php","intro":"PHP-Framework für Webanwendungen. Hier stehen die Befehle und Schreibweisen, die in den Laravel-Lektionen vorkommen.","notice":"Diese Beispiele werden nicht ausgeführt. Sie zeigen die Schreibweisen aus den Laravel-Lektionen; Befehle laufen im Projektordner einer Laravel-Anwendung.","runner":"","entries":[{"id":"laravel-artisan","cat":"Artisan (Terminal)","term":"php artisan make:…","syntax":"php artisan make:model Aufgabe -mfc","text":"Erzeugt Dateien mit der richtigen Struktur. Die Optionen -m, -f und -c legen zusätzlich Migration, Factory und Controller an.","code":"php artisan make:model Aufgabe -mf\nphp artisan make:controller AufgabeController --resource\nphp artisan make:request AufgabeRequest","pitfall":"Der Befehl läuft im Projektordner. Dateinamen und Namensräume folgen den Laravel-Konventionen, nicht verschieben ohne Anpassung.","lesson":"m45-l1","tested":false},{"id":"laravel-route","cat":"Routing","term":"Route::get / post / resource","syntax":"Route::get('/pfad', [Controller::class, 'methode'])->name('name');","text":"Verknüpft eine URL und eine HTTP-Methode mit Code. name() vergibt einen Namen, mit dem sich URLs per route() erzeugen lassen. resource() legt die sieben üblichen CRUD-Routen an.","code":"use App\\Http\\Controllers\\AufgabeController;\nuse Illuminate\\Support\\Facades\\Route;\n\nRoute::get('/aufgaben', [AufgabeController::class, 'index'])->name('aufgaben.index');\nRoute::resource('aufgaben', AufgabeController::class)->except(['show']);","pitfall":"Formularrouten (POST, PUT, DELETE) brauchen @csrf im Formular, sonst antwortet Laravel mit Fehler 419.","lesson":"m45-l2","tested":false},{"id":"laravel-route-param","cat":"Routing","term":"Routenparameter und Model Binding","syntax":"Route::get('/aufgaben/{aufgabe}', fn (Aufgabe $aufgabe) => …);","text":"Platzhalter in geschweiften Klammern werden an die Funktion übergeben. Ist der Parametername gleich dem Variablennamen eines Models, lädt Laravel den Datensatz selbst und antwortet bei Nichtfund mit 404.","code":"Route::get('/aufgaben/{aufgabe}', function (Aufgabe $aufgabe) {\n    return view('aufgaben.show', ['aufgabe' => $aufgabe]);\n});","pitfall":"Model Binding prüft nicht, ob der Nutzer den Datensatz sehen darf. Dafür Policies oder Gates verwenden.","lesson":"m45-l2","tested":false},{"id":"laravel-controller","cat":"Controller","term":"Controller-Methode","syntax":"public function store(Request $request): RedirectResponse","text":"Nimmt die Anfrage entgegen, ruft Logik auf und liefert Antwort: eine View, eine Weiterleitung oder JSON. Controller sollen schlank bleiben.","code":"public function store(AufgabeRequest $request): RedirectResponse\n{\n    Aufgabe::create($request->validated());\n\n    return redirect()->route('aufgaben.index')->with('status', 'Gespeichert');\n}","pitfall":"Nie $request->all() an create() übergeben. validated() liefert nur geprüfte Felder, so vermeidet man Mass-Assignment-Lücken.","lesson":"m45-l3","tested":false},{"id":"laravel-blade","cat":"Blade-Templates","term":"{{ }}, @if, @foreach","syntax":"{{ $variable }}    @if (…) … @endif    @foreach ($liste as $x) … @endforeach","text":"Blade ist die Template-Sprache. {{ }} gibt Werte maskiert aus (Schutz vor XSS). @if, @foreach, @forelse und @include steuern die Ausgabe. {!! !!} gibt rohes HTML aus.","code":"@forelse ($aufgaben as $aufgabe)\n    <li>{{ $aufgabe->titel }}</li>\n@empty\n    <li>Keine Aufgaben</li>\n@endforelse","pitfall":"{!! !!} nur für HTML, das du selbst erzeugt oder bereinigt hast. Nutzertexte gehören immer in {{ }}.","lesson":"m45-l3","tested":false,"codeLang":"blade"},{"id":"laravel-blade-component","cat":"Blade-Templates","term":"Blade-Komponente","syntax":"<x-karte titel=\"…\">Inhalt</x-karte>","text":"Wiederverwendbares Stück Oberfläche. Attribute werden zu Variablen, der Inhalt steht in $slot, benannte Slots mit <x-slot:name>.","code":"{{-- resources/views/components/karte.blade.php --}}\n@props(['titel'])\n<section class=\"karte\">\n    <h2>{{ $titel }}</h2>\n    {{ $slot }}\n</section>\n\n{{-- Verwendung --}}\n<x-karte titel=\"Heute\">Drei Aufgaben offen.</x-karte>","pitfall":"Dynamische Werte werden mit Doppelpunkt übergeben: :anzahl=\"$n\". Ohne Doppelpunkt kommt der Text „$n“ an.","lesson":"m56-l1","tested":false,"codeLang":"blade"},{"id":"laravel-migration","cat":"Datenbank","term":"Migration","syntax":"Schema::create('tabelle', function (Blueprint $table) { … });","text":"Beschreibt Änderungen am Datenbankschema in Code. php artisan migrate führt sie aus, migrate:rollback macht den letzten Schritt rückgängig.","code":"Schema::create('aufgaben', function (Blueprint $table) {\n    $table->id();\n    $table->string('titel');\n    $table->boolean('erledigt')->default(false);\n    $table->foreignId('user_id')->constrained()->cascadeOnDelete();\n    $table->timestamps();\n});","pitfall":"Bereits veröffentlichte Migrationen nicht nachträglich ändern. Stattdessen eine neue Migration anlegen.","lesson":"m46-l1","tested":false},{"id":"laravel-eloquent","cat":"Datenbank","term":"Eloquent-Model","syntax":"class Aufgabe extends Model { protected $fillable = ['titel']; }","text":"Ein Model entspricht einer Tabelle. $fillable legt fest, welche Felder per Mass Assignment gesetzt werden dürfen. Abfragen laufen über Methoden wie where(), orderBy(), find() und create().","code":"$offene = Aufgabe::query()\n    ->where('erledigt', false)\n    ->orderByDesc('created_at')\n    ->limit(10)\n    ->get();\n\n$aufgabe = Aufgabe::findOrFail($id);\n$aufgabe->update(['erledigt' => true]);","pitfall":"findOrFail antwortet bei Nichtfund mit 404, find liefert null. Auf null prüfen oder findOrFail verwenden.","lesson":"m46-l2","tested":false},{"id":"laravel-relations","cat":"Datenbank","term":"Beziehungen","syntax":"hasMany, belongsTo, belongsToMany","text":"Beziehungen werden als Methode im Model deklariert und wie eine Eigenschaft gelesen ($user->aufgaben). hasMany ist die „1“-Seite, belongsTo die „n“-Seite.","code":"class User extends Model\n{\n    public function aufgaben(): HasMany\n    {\n        return $this->hasMany(Aufgabe::class);\n    }\n}\n\nclass Aufgabe extends Model\n{\n    public function user(): BelongsTo\n    {\n        return $this->belongsTo(User::class);\n    }\n}","pitfall":"In Schleifen entsteht schnell das N+1-Problem. Mit with('aufgaben') vorab laden.","lesson":"m46-l3","tested":false},{"id":"laravel-eager","cat":"Datenbank","term":"with (Eager Loading)","syntax":"User::with('aufgaben')->get()","text":"Lädt Beziehungen in einer zusätzlichen Abfrage für alle Datensätze gemeinsam, statt pro Datensatz eine neue Abfrage zu stellen.","code":"$nutzer = User::with('aufgaben:id,user_id,titel')->get();\nforeach ($nutzer as $u) {\n    echo $u->aufgaben->count();\n}","pitfall":"Mit Model::preventLazyLoading() in Entwicklung und Tests fallen vergessene with()-Aufrufe sofort auf.","lesson":"m46-l4","tested":false},{"id":"laravel-validate","cat":"Validierung","term":"Form Request","syntax":"public function rules(): array { return ['feld' => ['required', 'string']]; }","text":"Eine eigene Klasse prüft die Eingaben, bevor der Controller läuft. Bei Fehlern leitet Laravel zurück und füllt $errors für Blade. Bei JSON-Anfragen antwortet es mit Status 422.","code":"public function rules(): array\n{\n    return [\n        'titel' => ['required', 'string', 'max:120'],\n        'faellig' => ['nullable', 'date', 'after:today'],\n    ];\n}","pitfall":"Validierung ersetzt nicht die Autorisierung. Wer die Aufgabe ändern darf, regelt authorize() oder eine Policy.","lesson":"m47-l1","tested":false},{"id":"laravel-auth","cat":"Sicherheit","term":"auth, @csrf, Gates","syntax":"Route::middleware('auth')->group(…);    @csrf    $this->authorize('update', $aufgabe);","text":"Die Middleware auth schützt Routen vor Anonymen. @csrf fügt dem Formular den Token gegen Cross-Site-Request-Forgery hinzu. authorize() prüft über Gates und Policies, ob der angemeldete Nutzer etwas darf.","code":"Route::middleware('auth')->group(function () {\n    Route::resource('aufgaben', AufgabeController::class);\n});\n\n// im Controller\n$this->authorize('update', $aufgabe);","pitfall":"Angemeldet heißt nicht berechtigt. Jede Aktion auf einem fremden Datensatz braucht zusätzlich eine Policy-Prüfung.","lesson":"m47-l2","tested":false},{"id":"laravel-api-resource","cat":"APIs","term":"JsonResource","syntax":"return new AufgabeResource($aufgabe);","text":"Legt fest, welche Felder die API ausgibt. So hängt das JSON-Format nicht direkt an der Tabellenstruktur.","code":"class AufgabeResource extends JsonResource\n{\n    public function toArray(Request $request): array\n    {\n        return [\n            'id' => $this->id,\n            'titel' => $this->titel,\n            'erledigt' => $this->erledigt,\n        ];\n    }\n}","pitfall":"Keine internen Felder (Passwort-Hash, Notizen) ausgeben. Nur Felder aufführen, die der Client wirklich braucht.","lesson":"m48-l1","tested":false},{"id":"laravel-queue","cat":"Betrieb","term":"Job und dispatch","syntax":"MeinJob::dispatch($daten);    php artisan queue:work","text":"Ein Job ist Arbeit, die im Hintergrund läuft, etwa E-Mails senden. dispatch() legt sie in die Warteschlange, ein Worker (queue:work) arbeitet sie ab.","code":"class RechnungErzeugen implements ShouldQueue\n{\n    use Queueable;\n\n    public function __construct(public int $bestellungId) {}\n\n    public function handle(): void\n    {\n        // Rechnung erzeugen …\n    }\n}\n\nRechnungErzeugen::dispatch($bestellung->id);","pitfall":"Jobs können mehrfach laufen. Die Arbeit muss idempotent sein, also ein zweiter Lauf darf nichts doppelt tun.","lesson":"m50-l1","tested":false},{"id":"laravel-test","cat":"Betrieb","term":"Feature-Test","syntax":"$this->get('/pfad')->assertOk();","text":"Ruft Routen wie ein Browser auf und prüft Antworten und Datenbankzustand. RefreshDatabase setzt die Datenbank pro Test zurück.","code":"it('zeigt die Aufgabenliste', function () {\n    $user = User::factory()->create();\n\n    $this->actingAs($user)\n        ->get('/aufgaben')\n        ->assertOk();\n});","pitfall":"Tests gegen eine echte Entwicklungsdatenbank können Daten löschen. Für Tests eine eigene Datenbank verwenden.","lesson":"m51-l1","tested":false}]},{"id":"java","label":"Java","codeLang":"java","intro":"Statisch typisierte, objektorientierte Sprache. Jede Anweisung endet mit Semikolon, Blöcke stehen in geschweiften Klammern.","notice":"Die Beispiele mit Markierung sind mit Java 26 ausgeführt und geprüft. Spring- und JUnit-Ausschnitte brauchen ein Projekt mit den passenden Abhängigkeiten und werden nur gezeigt.","runner":"Java","entries":[{"id":"java-main","cat":"Grundlagen","term":"Hauptprogramm","syntax":"public static void main(String[] args)","text":"Startpunkt eines Programms. Die Klasse trägt den Namen der Datei. Mit „java Main.java“ lässt sich eine einzelne Datei direkt ausführen.","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"Hallo Welt\");\n    }\n}","out":"Hallo Welt","pitfall":"Dateiname und öffentliche Klasse müssen übereinstimmen: Main.java enthält public class Main.","lesson":"java-m7-l1","tested":true},{"id":"java-types","cat":"Typen","term":"Primitive Typen","syntax":"int  long  double  boolean  char","text":"Primitive Typen speichern den Wert direkt. int ist ganzzahlig (±2,1 Mrd.), long für größere Zahlen (Endung L), double für Kommazahlen, boolean für wahr/falsch.","code":"int a = 7;\nlong gross = 3_000_000_000L;\ndouble d = 7 / 2;\ndouble e = 7 / 2.0;\nSystem.out.println(d + \" \" + e + \" \" + gross);","out":"3.0 3.5 3000000000","pitfall":"7 / 2 ist bei ganzen Zahlen 3, nicht 3,5. Mindestens ein Operand muss double sein. Für Geld BigDecimal statt double nehmen.","lesson":"java-m7-l2","tested":true},{"id":"java-var","cat":"Typen","term":"var","syntax":"var name = ausdruck;","text":"Lässt den Compiler den Typ der lokalen Variablen ermitteln. Der Typ steht danach genauso fest wie bei ausdrücklicher Angabe.","code":"var liste = new ArrayList<String>();\nliste.add(\"a\");\nvar zahl = 42;\nSystem.out.println(liste + \" \" + zahl);","out":"[a] 42","pitfall":"var nur nutzen, wenn der Typ aus der rechten Seite klar ablesbar ist. Es gibt kein var für Felder und Parameter.","lesson":"java-m7-l2","tested":true},{"id":"java-string","cat":"Strings","term":"String-Methoden","syntax":"length()  charAt()  substring()  equals()  strip()  split()","text":"Strings sind unveränderlich: jede Methode liefert einen neuen String. Inhalte vergleicht man mit equals(), nicht mit ==.","code":"String s = \"  Hallo Welt \";\nSystem.out.println(s.strip().toUpperCase());\nSystem.out.println(\"a\".equals(\"a\") + \" \" + \"Hallo\".substring(1, 3));\nSystem.out.println(String.join(\"-\", \"a b c\".split(\" \")));","out":"HALLO WELT\ntrue al\na-b-c","pitfall":"== vergleicht Referenzen, nicht Inhalt. Bei new String(\"a\") == \"a\" ist das Ergebnis false.","lesson":"java-m7-l3","tested":true},{"id":"java-textblock","cat":"Strings","term":"Textblock und formatted","syntax":"\"\"\"\n  Text\n  \"\"\"","text":"Mehrzeiliger Text zwischen drei Anführungszeichen. Die gemeinsame Einrückung wird entfernt. formatted() setzt Werte wie bei printf ein.","code":"String json = \"\"\"\n    {\"name\": \"%s\", \"alter\": %d}\n    \"\"\".formatted(\"Ada\", 36);\nSystem.out.print(json);","out":"{\"name\": \"Ada\", \"alter\": 36}","pitfall":"Nie Nutzereingaben auf diese Weise in JSON, HTML oder SQL einsetzen. Dafür Bibliotheken oder PreparedStatement verwenden.","lesson":"java-m7-l3","tested":true},{"id":"java-if-switch","cat":"Kontrollfluss","term":"switch-Ausdruck","syntax":"var x = switch (wert) { case A, B -> … ; default -> …; };","text":"Gibt einen Wert zurück, hat keinen Durchfall-Effekt und prüft bei enums und sealed Typen auf Vollständigkeit. Mit -> statt : entfällt das break.","code":"String tag = \"SA\";\nString art = switch (tag) {\n    case \"SA\", \"SO\" -> \"Wochenende\";\n    default -> \"Werktag\";\n};\nSystem.out.println(art);","out":"Wochenende","pitfall":"Ohne default muss der switch bei Strings und Zahlen trotzdem alle Fälle abdecken, sonst Compilerfehler. Bei enums reicht eine vollständige Liste.","lesson":"java-m7-l4","tested":true},{"id":"java-for","cat":"Kontrollfluss","term":"for und for-each","syntax":"for (int i = 0; i < n; i++) { … }    for (var x : liste) { … }","text":"Die klassische for-Schleife zählt, die erweiterte for-Schleife läuft über alle Elemente einer Sammlung. while läuft, solange die Bedingung gilt.","code":"int summe = 0;\nfor (int i = 1; i <= 4; i++) summe += i;\nfor (var s : List.of(\"a\", \"b\")) System.out.print(s);\nSystem.out.println(\" \" + summe);","out":"ab 10","pitfall":"In einer for-each-Schleife darf man die Sammlung nicht verändern (ConcurrentModificationException). Dafür removeIf() oder einen Iterator verwenden.","lesson":"java-m9-l4","tested":true},{"id":"java-class","cat":"Klassen","term":"class, Konstruktor, Methoden","syntax":"class Name { private Typ feld; Name(Typ f) { … } }","text":"Eine Klasse bündelt Daten (Felder) und Verhalten (Methoden). Der Konstruktor hat den Namen der Klasse. private schützt Felder, Zugriff erfolgt über Methoden.","code":"class Konto {\n    private int stand;\n    void einzahlen(int betrag) {\n        if (betrag <= 0) throw new IllegalArgumentException(\"Betrag muss positiv sein\");\n        stand += betrag;\n    }\n    int stand() { return stand; }\n}\nKonto k = new Konto();\nk.einzahlen(50);\nSystem.out.println(k.stand());","out":"50","pitfall":"Felder nicht public machen. Sonst kann jeder den Zustand ohne Prüfung ändern.","lesson":"java-m8-l1","tested":true},{"id":"java-interface","cat":"Klassen","term":"interface und extends","syntax":"interface Name { Typ methode(); }    class A implements Name","text":"Ein Interface legt fest, was eine Klasse können muss. Eine Klasse kann mehrere Interfaces implementieren, aber nur von einer Klasse erben (extends).","code":"interface Tier { String laut(); }\nclass Hund implements Tier {\n    public String laut() { return \"Wuff\"; }\n}\nTier t = new Hund();\nSystem.out.println(t.laut());","out":"Wuff","pitfall":"Methoden eines Interfaces sind automatisch public. Beim Implementieren muss public vor der Methode stehen.","lesson":"java-m8-l3","tested":true},{"id":"java-record","cat":"Klassen","term":"record","syntax":"record Name(Typ a, Typ b) { }","text":"Kompakte, unveränderliche Datenklasse. Konstruktor, Zugriffsmethoden, equals, hashCode und toString entstehen automatisch. Im kompakten Konstruktor lässt sich prüfen.","code":"record Punkt(int x, int y) {\n    Punkt {\n        if (x < 0) throw new IllegalArgumentException(\"x < 0\");\n    }\n}\nvar p = new Punkt(1, 2);\nSystem.out.println(p + \" \" + p.x() + \" \" + p.equals(new Punkt(1, 2)));","out":"Punkt[x=1, y=2] 1 true","pitfall":"Records sind flach unveränderlich. Enthält ein Record eine veränderliche Liste, bleibt die Liste veränderlich. Mit List.copyOf() absichern.","lesson":"java-m8-l4","tested":true},{"id":"java-enum","cat":"Klassen","term":"enum","syntax":"enum Name { A, B, C }","text":"Feste Menge benannter Werte. Enums können Felder und Methoden haben und eignen sich gut für switch.","code":"enum Status {\n    OFFEN(\"offen\"), FERTIG(\"fertig\");\n    private final String text;\n    Status(String text) { this.text = text; }\n    String text() { return text; }\n}\nSystem.out.println(Status.valueOf(\"FERTIG\").text() + \" \" + Status.values().length);","out":"fertig 2","pitfall":"valueOf wirft bei unbekanntem Namen eine IllegalArgumentException. Eingaben von außen abfangen oder vorher prüfen.","lesson":"java-m8-l4","tested":true},{"id":"java-sealed","cat":"Klassen","term":"sealed interface mit Pattern Matching","syntax":"sealed interface Form permits A, B { }","text":"Legt fest, welche Typen ein Interface implementieren dürfen. Ein switch über alle erlaubten Typen braucht dann kein default, und der Compiler meldet fehlende Fälle.","code":"public class Main {\n    sealed interface Form permits Kreis, Quadrat {}\n    record Kreis(double r) implements Form {}\n    record Quadrat(double a) implements Form {}\n\n    static double flaeche(Form f) {\n        return switch (f) {\n            case Kreis k -> Math.PI * k.r() * k.r();\n            case Quadrat q -> q.a() * q.a();\n        };\n    }\n\n    public static void main(String[] args) {\n        System.out.println(flaeche(new Quadrat(3)));\n    }\n}","out":"9.0","pitfall":"Kommt ein neuer Typ hinzu, bricht jeder switch ohne default beim Kompilieren. Das ist gewollt: kein Fall wird vergessen.","lesson":"java-m25-l2","tested":true},{"id":"java-pattern","cat":"Typen","term":"instanceof-Pattern und Record-Pattern","syntax":"if (o instanceof String s) { … }    case Punkt(int x, int y) ->","text":"Prüft den Typ und bindet das Ergebnis gleich an eine Variable. Record-Pattern zerlegen einen Record direkt in seine Komponenten.","code":"record Punkt(int x, int y) {}\nObject o = new Punkt(3, 4);\nif (o instanceof Punkt(int x, int y) && x < y) {\n    System.out.println(\"x=\" + x + \", y=\" + y);\n}\nObject s = \"Text\";\nif (s instanceof String t) System.out.println(t.length());","out":"x=3, y=4\n4","pitfall":"Die Pattern-Variable gilt nur dort, wo der Compiler den Typ sicher kennt (im if-Zweig, nicht danach).","lesson":"java-m25-l1","tested":true},{"id":"java-collections","cat":"Sammlungen","term":"List, Set, Map","syntax":"List<String>  Set<String>  Map<String, Integer>","text":"List behält die Reihenfolge und erlaubt Doppelte, Set kennt jedes Element nur einmal, Map verknüpft Schlüssel mit Werten. List.of und Map.of liefern unveränderliche Sammlungen.","code":"var liste = new ArrayList<>(List.of(\"b\", \"a\", \"b\"));\nvar menge = new TreeSet<>(liste);\nvar zaehler = new TreeMap<String, Integer>();\nfor (var s : liste) zaehler.merge(s, 1, Integer::sum);\nSystem.out.println(liste + \" \" + menge + \" \" + zaehler);","out":"[b, a, b] [a, b] {a=1, b=2}","pitfall":"List.of() ist unveränderlich: add() wirft UnsupportedOperationException. Für eine veränderbare Kopie new ArrayList<>(…) benutzen.","lesson":"java-m9-l1","tested":true},{"id":"java-generics","cat":"Sammlungen","term":"Generics","syntax":"class Kiste<T> { … }    <T extends Comparable<T>> T max(List<T> l)","text":"Typparameter lassen Klassen und Methoden für verschiedene Typen arbeiten, ohne den Typ zu verlieren. Mit extends lässt sich eine Fähigkeit voraussetzen.","code":"static <T extends Comparable<T>> T groesster(List<T> liste) {\n    T max = liste.get(0);\n    for (T t : liste) if (t.compareTo(max) > 0) max = t;\n    return max;\n}\npublic static void main(String[] args) {\n    System.out.println(groesster(List.of(3, 9, 4)) + \" \" + groesster(List.of(\"a\", \"z\")));\n}","out":"9 z","pitfall":"Generische Typen sind zur Laufzeit gelöscht (Type Erasure). new T() und instanceof List<String> sind nicht möglich.","lesson":"java-m9-l3","tested":true},{"id":"java-lambda","cat":"Funktional","term":"Lambda und Methodenreferenz","syntax":"(a, b) -> a + b    Klasse::methode","text":"Ein Lambda ist eine Kurzform für eine Funktion, die als Wert übergeben wird. Es passt zu jedem Interface mit genau einer abstrakten Methode (z. B. Function, Predicate, Comparator).","code":"Function<Integer, Integer> doppelt = x -> x * 2;\nPredicate<String> leer = String::isBlank;\nvar namen = new ArrayList<>(List.of(\"Eva\", \"Al\", \"Bob\"));\nnamen.sort(Comparator.comparing(String::length).thenComparing(Comparator.naturalOrder()));\nSystem.out.println(doppelt.apply(21) + \" \" + leer.test(\" \") + \" \" + namen);","out":"42 true [Al, Bob, Eva]","pitfall":"Lambdas dürfen nur lokale Variablen lesen, die effektiv final sind. Zähler in Lambdas brauchen z. B. AtomicInteger oder einen Stream-Ansatz.","lesson":"java-m11-l1","tested":true},{"id":"java-stream","cat":"Funktional","term":"Stream-Pipeline","syntax":"liste.stream().filter(…).map(…).toList()","text":"Verarbeitet Daten in Schritten: Quelle, Zwischenoperationen (filter, map, sorted), Endoperation (toList, collect, sum, count). Erst die Endoperation startet die Arbeit.","code":"var ergebnis = List.of(5, 12, 8, 20).stream()\n    .filter(n -> n > 7)\n    .map(n -> n * 2)\n    .sorted()\n    .toList();\nSystem.out.println(ergebnis);","out":"[16, 24, 40]","pitfall":"Ein Stream lässt sich nur einmal verwenden. Wer Zwischenergebnisse braucht, speichert sie in einer Liste.","lesson":"java-m11-l2","tested":true},{"id":"java-collectors","cat":"Funktional","term":"Collectors.groupingBy","syntax":"stream.collect(Collectors.groupingBy(klassifizierer, …))","text":"Sammelt Stream-Elemente in Gruppen. Mit einem zweiten Collector (counting, summingInt, mapping) wird jede Gruppe weiter verarbeitet.","code":"var nachLaenge = Stream.of(\"ab\", \"cd\", \"efg\", \"h\")\n    .collect(Collectors.groupingBy(String::length, TreeMap::new, Collectors.counting()));\nSystem.out.println(nachLaenge);","out":"{1=1, 2=2, 3=1}","pitfall":"Collectors.toMap wirft bei doppelten Schlüsseln eine Ausnahme, wenn keine Zusammenführungsfunktion angegeben ist.","lesson":"java-m11-l3","tested":true},{"id":"java-optional","cat":"Funktional","term":"Optional","syntax":"Optional<T>    map(…)    orElse(…)    orElseThrow()","text":"Beschreibt „Wert oder nichts“ als Rückgabetyp. map wandelt um, orElse liefert einen Ersatz, orElseThrow wirft bei leerem Optional.","code":"Optional<String> name = Optional.of(\"ada\");\nSystem.out.println(name.map(String::toUpperCase).orElse(\"?\"));\nSystem.out.println(Optional.<String>empty().orElse(\"leer\"));","out":"ADA\nleer","pitfall":"Optional ist für Rückgabewerte gedacht, nicht für Felder oder Parameter. get() ohne Prüfung wirft NoSuchElementException.","lesson":"java-m11-l4","tested":true},{"id":"java-exception","cat":"Fehler","term":"try / catch / finally","syntax":"try { … } catch (Typ e) { … } finally { … }","text":"Fängt Ausnahmen. Checked Exceptions (z. B. IOException) muss man behandeln oder mit throws weitergeben, RuntimeExceptions nicht. finally läuft immer.","code":"try {\n    Integer.parseInt(\"abc\");\n} catch (NumberFormatException e) {\n    System.out.println(\"Ungültig: \" + e.getMessage());\n} finally {\n    System.out.println(\"fertig\");\n}","out":"Ungültig: For input string: \"abc\"\nfertig","pitfall":"Leere catch-Blöcke verschlucken Fehler. Wenigstens protokollieren oder weiterwerfen.","lesson":"java-m10-l1","tested":true},{"id":"java-twr","cat":"Fehler","term":"try-with-resources","syntax":"try (var r = new Resource()) { … }","text":"Schließt Ressourcen (Dateien, Verbindungen) am Blockende automatisch, auch bei Fehlern. Die Ressource muss AutoCloseable sein.","code":"class Tor implements AutoCloseable {\n    Tor() { System.out.println(\"auf\"); }\n    public void close() { System.out.println(\"zu\"); }\n}\ntry (var t = new Tor()) {\n    System.out.println(\"arbeiten\");\n}","out":"auf\narbeiten\nzu","pitfall":"Ohne try-with-resources bleiben Dateien und Datenbankverbindungen bei Fehlern offen (Ressourcenleck).","lesson":"java-m10-l2","tested":true},{"id":"java-equals","cat":"Klassen","term":"equals und hashCode","syntax":"@Override public boolean equals(Object o) …    public int hashCode()","text":"equals definiert, wann zwei Objekte gleich sind, hashCode muss dazu passen (gleiche Objekte, gleicher Hash). Ohne beides funktionieren HashSet und HashMap nicht wie erwartet. Records und IDEs erzeugen sie.","code":"class Euro {\n    final int cent;\n    Euro(int cent) { this.cent = cent; }\n    @Override public boolean equals(Object o) { return o instanceof Euro e && e.cent == cent; }\n    @Override public int hashCode() { return Integer.hashCode(cent); }\n}\nvar set = new HashSet<Euro>();\nset.add(new Euro(100));\nSystem.out.println(set.contains(new Euro(100)));","out":"true","pitfall":"Wer nur equals überschreibt, bricht den Vertrag: Das Objekt wird in HashMap/HashSet womöglich nicht wiedergefunden.","lesson":"java-m9-l2","tested":true},{"id":"java-time","cat":"Daten","term":"java.time","syntax":"LocalDate.of(…)    plusDays(…)    DateTimeFormatter.ofPattern(…)","text":"Die moderne Datum-Zeit-API. LocalDate ohne Uhrzeit, LocalDateTime ohne Zone, ZonedDateTime und Instant mit Bezug zur Weltzeit. Alle Objekte sind unveränderlich.","code":"var d = LocalDate.of(2026, 1, 31);\nSystem.out.println(d.plusMonths(1) + \" \" + d.getDayOfWeek() + \" \" + d.format(java.time.format.DateTimeFormatter.ofPattern(\"dd.MM.yyyy\")));","out":"2026-02-28 SATURDAY 31.01.2026","pitfall":"Auf java.util.Date und SimpleDateFormat verzichten. Sie sind veränderlich und nicht threadsicher.","lesson":"java-m14-l1","tested":true},{"id":"java-thread","cat":"Nebenläufigkeit","term":"ExecutorService","syntax":"try (var ex = Executors.newFixedThreadPool(4)) { … }","text":"Verwaltet einen Pool von Threads. submit() startet eine Aufgabe und liefert ein Future. Ab Java 19 schließt try-with-resources den Executor und wartet auf die Aufgaben.","code":"try (var ex = java.util.concurrent.Executors.newFixedThreadPool(2)) {\n    var f = ex.submit(() -> 6 * 7);\n    System.out.println(f.get());\n}","out":"42","pitfall":"Gemeinsam genutzte veränderliche Daten ohne Synchronisation führen zu Race Conditions. Unveränderliche Objekte oder Atomic-Klassen bevorzugen.","lesson":"java-m13-l3","tested":true},{"id":"java-vthread","cat":"Nebenläufigkeit","term":"Virtual Threads","syntax":"Thread.ofVirtual().start(…)    Executors.newVirtualThreadPerTaskExecutor()","text":"Leichtgewichtige Threads für viele gleichzeitig wartende Aufgaben (Netzwerk, Datenbank). Man legt pro Aufgabe einen eigenen Thread an und muss sie nicht poolen.","code":"try (var ex = java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()) {\n    var f = ex.submit(() -> Thread.currentThread().isVirtual());\n    System.out.println(f.get());\n}","out":"true","pitfall":"Virtual Threads helfen bei Warten (I/O), nicht bei reiner Rechenlast. Dafür bleibt die Zahl der CPU-Kerne die Grenze.","lesson":"java-m25-l4","tested":true},{"id":"java-completable","cat":"Nebenläufigkeit","term":"CompletableFuture","syntax":"CompletableFuture.supplyAsync(…).thenApply(…).thenCombine(…)","text":"Beschreibt Ergebnisse, die später vorliegen, und verkettet Schritte. join() wartet auf das Ergebnis, exceptionally behandelt Fehler.","code":"var a = java.util.concurrent.CompletableFuture.supplyAsync(() -> 20);\nvar b = java.util.concurrent.CompletableFuture.supplyAsync(() -> 22);\nSystem.out.println(a.thenCombine(b, Integer::sum).join());","out":"42","pitfall":"Ohne eigenen Executor nutzt supplyAsync den gemeinsamen Pool. Blockierende Aufrufe darin bremsen alle anderen Aufgaben.","lesson":"java-m13-l4","tested":true},{"id":"java-files","cat":"Daten","term":"Files (NIO.2)","syntax":"Files.readString(path)    Files.writeString(path, text)    Files.lines(path)","text":"Liest und schreibt Dateien. Path beschreibt den Pfad. Files.lines liefert einen Stream, der nach Gebrauch geschlossen werden muss (try-with-resources).","code":"var pfad = java.nio.file.Files.createTempFile(\"glossar\", \".txt\");\njava.nio.file.Files.writeString(pfad, \"a\\nb\\n\");\ntry (var zeilen = java.nio.file.Files.lines(pfad)) {\n    System.out.println(zeilen.count());\n}\njava.nio.file.Files.delete(pfad);","out":"2","pitfall":"Pfade aus Nutzereingaben mit normalize() und einem Basisordner prüfen, sonst droht Path Traversal (../).","lesson":"java-m14-l2","tested":true},{"id":"java-junit","cat":"Tests","term":"JUnit 5","syntax":"@Test void …() { assertEquals(erwartet, tatsaechlich); }","text":"Ein Test ist eine Methode mit @Test. Assertions prüfen das Ergebnis, assertThrows erwartet eine Ausnahme. Gute Tests heißen nach dem Verhalten, das sie prüfen.","code":"class RechnerTest {\n    @Test\n    void additionLiefertSumme() {\n        assertEquals(5, new Rechner().add(2, 3));\n    }\n\n    @Test\n    void divisionDurchNullWirftFehler() {\n        assertThrows(ArithmeticException.class, () -> new Rechner().div(1, 0));\n    }\n}","pitfall":"Bei assertEquals steht der erwartete Wert zuerst. Vertauschte Argumente erzeugen irreführende Fehlermeldungen.","lesson":"java-m15-l1","tested":false},{"id":"java-spring-controller","cat":"Spring Boot","term":"@RestController","syntax":"@RestController @RequestMapping('/api/…')","text":"Markiert eine Klasse, deren Methoden HTTP-Anfragen beantworten. @GetMapping, @PostMapping usw. ordnen Pfad und Methode zu. @PathVariable und @RequestBody holen Daten aus URL und Rumpf.","code":"@RestController\n@RequestMapping(\"/api/aufgaben\")\nclass AufgabeController {\n    private final AufgabeService service;\n\n    AufgabeController(AufgabeService service) { this.service = service; }\n\n    @GetMapping(\"/{id}\")\n    AufgabeDto lesen(@PathVariable long id) { return service.finde(id); }\n\n    @PostMapping\n    @ResponseStatus(HttpStatus.CREATED)\n    AufgabeDto anlegen(@Valid @RequestBody AufgabeRequest request) { return service.anlegen(request); }\n}","pitfall":"Entities nicht direkt als Antwort zurückgeben. DTOs entkoppeln die API von der Datenbank und verhindern, dass interne Felder ausgeliefert werden.","lesson":"java-m22-l1","tested":false},{"id":"java-spring-injection","cat":"Spring Boot","term":"Konstruktorinjektion","syntax":"@Service class A { A(B b) { … } }","text":"Spring übergibt die benötigten Beans über den Konstruktor. So sind Abhängigkeiten sichtbar, Felder können final sein, und Tests brauchen kein Spring.","code":"@Service\nclass RechnungService {\n    private final RechnungRepository repository;\n\n    RechnungService(RechnungRepository repository) {\n        this.repository = repository;\n    }\n}","pitfall":"Feldinjektion mit @Autowired versteckt Abhängigkeiten und macht Tests schwer. Konstruktorinjektion bevorzugen.","lesson":"java-m21-l2","tested":false},{"id":"java-spring-repo","cat":"Spring Boot","term":"Spring Data Repository","syntax":"interface XRepository extends JpaRepository<X, Long>","text":"Ein Interface genügt, Spring erzeugt die Implementierung. Abfragemethoden werden aus dem Namen abgeleitet (findByStatus, existsByEmail). Mit @Query schreibt man eigene Abfragen.","code":"interface AufgabeRepository extends JpaRepository<Aufgabe, Long> {\n    List<Aufgabe> findByErledigtFalseOrderByFaelligAsc();\n\n    @Query(\"select a from Aufgabe a where a.titel like %:text%\")\n    Page<Aufgabe> suche(String text, Pageable pageable);\n}","pitfall":"Beziehungen werden standardmäßig nachgeladen (Lazy). In Schleifen führt das zum N+1-Problem, daher fetch join oder EntityGraph einsetzen.","lesson":"java-m23-l1","tested":false},{"id":"java-spring-transactional","cat":"Spring Boot","term":"@Transactional","syntax":"@Transactional public void methode()","text":"Führt die Methode in einer Datenbanktransaktion aus: Alles oder nichts. Bei einer RuntimeException wird zurückgerollt.","code":"@Transactional\npublic void ueberweisen(long von, long nach, BigDecimal betrag) {\n    konten.abbuchen(von, betrag);\n    konten.gutschreiben(nach, betrag);\n}","pitfall":"Ruft eine Methode eine @Transactional-Methode derselben Klasse auf (this.…), greift die Transaktion nicht, weil der Aufruf am Proxy vorbeigeht.","lesson":"java-m23-l2","tested":false},{"id":"java-spring-validation","cat":"Spring Boot","term":"Bean Validation","syntax":"@NotBlank  @Size  @Email  @Valid","text":"Annotationen an Feldern beschreiben Regeln. @Valid am Parameter löst die Prüfung aus, bei Verstoß antwortet Spring mit 400.","code":"record AufgabeRequest(\n    @NotBlank @Size(max = 120) String titel,\n    @Future LocalDate faellig\n) {}","pitfall":"Validierung am Rand (Request) ersetzt keine Regeln in der Fachlogik. Wichtige Invarianten gehören auch dorthin.","lesson":"java-m22-l2","tested":false}]},{"id":"sql","label":"SQL (MariaDB)","codeLang":"sql","intro":"Abfragesprache für relationale Datenbanken. Alle Beispiele nutzen dieselben Tabellen kunde und bestellung (siehe „Ausgangsdaten“).","notice":"Die Beispiele mit Markierung laufen in SQLite und zeigen den gemeinsamen SQL-Kern. MariaDB kann in Details abweichen (Typen, AUTO_INCREMENT, Ausgabeformat). MariaDB-Besonderheiten werden nur gezeigt.","runner":"SQLite","entries":[{"id":"sql-select","cat":"Abfragen","term":"SELECT … FROM … WHERE","syntax":"SELECT spalten FROM tabelle WHERE bedingung;","text":"Liest Zeilen aus einer Tabelle. Hinter SELECT stehen die Spalten, hinter FROM die Tabelle, WHERE filtert die Zeilen. Text steht in einfachen Anführungszeichen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name, stadt FROM kunde WHERE stadt = 'Berlin';","out":"Ada | Berlin","pitfall":"SELECT * liefert alle Spalten, auch später hinzugefügte. In Anwendungen die benötigten Spalten nennen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-order","cat":"Abfragen","term":"ORDER BY und LIMIT","syntax":"ORDER BY spalte [DESC]  LIMIT anzahl [OFFSET start]","text":"ORDER BY sortiert aufsteigend (ASC) oder absteigend (DESC). LIMIT begrenzt die Zahl der Zeilen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde ORDER BY name DESC LIMIT 2;","out":"Cy\nBo","pitfall":"Ohne ORDER BY ist die Reihenfolge nicht garantiert. LIMIT ohne Sortierung liefert zufällige Zeilen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-null","cat":"Abfragen","term":"IS NULL","syntax":"WHERE spalte IS NULL    WHERE spalte IS NOT NULL","text":"NULL bedeutet „kein Wert“. Es lässt sich nicht mit = prüfen, sondern nur mit IS NULL oder IS NOT NULL.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde WHERE stadt IS NULL;","out":"Cy","pitfall":"stadt = NULL ist nie wahr, auch nicht für leere Zeilen. NULL-Vergleiche liefern „unbekannt“ und filtern die Zeile heraus.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-like-in","cat":"Abfragen","term":"LIKE, IN, BETWEEN","syntax":"name LIKE 'A%'    id IN (1, 2)    betrag BETWEEN 5 AND 15","text":"LIKE sucht Muster (% steht für beliebig viele Zeichen, _ für genau eins). IN prüft auf eine Liste, BETWEEN schließt beide Grenzen ein.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde WHERE name LIKE 'A%' OR id IN (3);\nSELECT id FROM bestellung WHERE betrag BETWEEN 6 AND 12 ORDER BY id;","out":"Ada\nCy\n2\n3","pitfall":"LIKE '%text%' kann keinen normalen Index nutzen und wird bei großen Tabellen langsam. Dafür Volltextsuche einsetzen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-distinct-alias","cat":"Abfragen","term":"DISTINCT und AS","syntax":"SELECT DISTINCT spalte AS alias FROM …","text":"DISTINCT entfernt doppelte Zeilen im Ergebnis. AS vergibt einen Namen für Spalten und Tabellen (Alias).","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT DISTINCT kunde_id AS kunde FROM bestellung ORDER BY kunde;","out":"1\n2","pitfall":"DISTINCT versteckt oft einen fehlerhaften Join. Erst prüfen, warum Duplikate entstehen, statt sie wegzufiltern.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-insert","cat":"Daten ändern","term":"INSERT","syntax":"INSERT INTO tabelle (spalten) VALUES (werte);","text":"Fügt eine Zeile ein. Die Spalten immer nennen, damit sich das Statement bei neuen Spalten nicht verschiebt.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"INSERT INTO kunde (id, name, stadt) VALUES (4, 'Di', 'Köln');\nSELECT COUNT(*) FROM kunde;","out":"4","pitfall":"Werte aus Nutzereingaben nie per Textverkettung einsetzen. Platzhalter verwenden (Prepared Statements), sonst droht SQL-Injection.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-update","cat":"Daten ändern","term":"UPDATE","syntax":"UPDATE tabelle SET spalte = wert WHERE bedingung;","text":"Ändert vorhandene Zeilen. Ohne WHERE werden alle Zeilen der Tabelle geändert.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"UPDATE kunde SET stadt = 'Bonn' WHERE id = 3;\nSELECT name, stadt FROM kunde WHERE id = 3;","out":"Cy | Bonn","pitfall":"Ein vergessenes WHERE ändert die ganze Tabelle. Vorher mit einem SELECT mit gleicher Bedingung prüfen und in einer Transaktion arbeiten.","lesson":"mariadb-m1-l4","tested":true},{"id":"sql-delete","cat":"Daten ändern","term":"DELETE","syntax":"DELETE FROM tabelle WHERE bedingung;","text":"Löscht Zeilen. Auch hier gilt: Ohne WHERE verschwinden alle Zeilen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"DELETE FROM bestellung WHERE id = 3;\nSELECT COUNT(*) FROM bestellung;","out":"2","pitfall":"Gelöscht ist gelöscht. Für Nachvollziehbarkeit oft ein Löschkennzeichen (deleted_at) statt echtem Löschen, sofern der Datenschutz nichts anderes verlangt.","lesson":"mariadb-m1-l4","tested":true},{"id":"sql-create","cat":"Schema","term":"CREATE TABLE mit Constraints","syntax":"CREATE TABLE name (spalte typ [NOT NULL] [UNIQUE] [CHECK (…)], PRIMARY KEY …)","text":"Legt eine Tabelle an. Constraints sichern Regeln in der Datenbank selbst: PRIMARY KEY (eindeutig), NOT NULL (Pflicht), UNIQUE (keine Doppelten), CHECK (Bedingung).","code":"CREATE TABLE produkt (\n  id INTEGER PRIMARY KEY,\n  name TEXT NOT NULL UNIQUE,\n  preis INTEGER CHECK (preis >= 0)\n);\nINSERT INTO produkt (name, preis) VALUES ('Tee', 3);\nSELECT * FROM produkt;","out":"1 | Tee | 3","pitfall":"In MariaDB heißt der automatische Zähler id INT AUTO_INCREMENT PRIMARY KEY, in SQLite genügt INTEGER PRIMARY KEY. Für kurze Texte nimmt man in MariaDB meist VARCHAR(100) statt TEXT.","lesson":"mariadb-m1-l2","tested":true},{"id":"sql-fk","cat":"Schema","term":"FOREIGN KEY","syntax":"FOREIGN KEY (spalte) REFERENCES andere_tabelle (id) ON DELETE …","text":"Verknüpft eine Spalte mit dem Primärschlüssel einer anderen Tabelle. Die Datenbank verhindert dann Verweise ins Leere. ON DELETE legt fest, was beim Löschen passiert (RESTRICT, CASCADE, SET NULL).","code":"CREATE TABLE bestellung (\n  id INT AUTO_INCREMENT PRIMARY KEY,\n  kunde_id INT NOT NULL,\n  betrag DECIMAL(10,2) NOT NULL,\n  FOREIGN KEY (kunde_id) REFERENCES kunde (id) ON DELETE RESTRICT\n) ENGINE = InnoDB;","pitfall":"Fremdschlüssel funktionieren in MariaDB nur mit InnoDB. Geldbeträge als DECIMAL speichern, nicht als FLOAT.","lesson":"mariadb-m1-l2","tested":false},{"id":"sql-alter","cat":"Schema","term":"ALTER TABLE","syntax":"ALTER TABLE tabelle ADD COLUMN spalte typ;","text":"Ändert eine bestehende Tabelle, etwa eine Spalte hinzufügen. Änderungen am Schema gehören in versionierte Migrationen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"ALTER TABLE kunde ADD COLUMN email TEXT;\nUPDATE kunde SET email = 'ada@example.org' WHERE id = 1;\nSELECT name, email FROM kunde WHERE id = 1;","out":"Ada | ada@example.org","pitfall":"Auf großen Tabellen sperren manche ALTER-Befehle lange. Vor dem Produktiveinsatz an einer Kopie testen.","lesson":"mariadb-m1-l2","tested":true},{"id":"sql-join","cat":"Joins","term":"INNER JOIN","syntax":"FROM a JOIN b ON a.id = b.a_id","text":"Verknüpft zwei Tabellen über zusammengehörende Werte. Der INNER JOIN liefert nur Zeilen, für die es auf beiden Seiten einen Treffer gibt.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT k.name, b.betrag\nFROM kunde k\nJOIN bestellung b ON b.kunde_id = k.id\nORDER BY b.id;","out":"Ada | 20\nAda | 6\nBo | 12","pitfall":"Kunde Cy ohne Bestellung fehlt im Ergebnis. Wer ihn sehen will, braucht einen LEFT JOIN.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-leftjoin","cat":"Joins","term":"LEFT JOIN","syntax":"FROM a LEFT JOIN b ON …","text":"Liefert alle Zeilen der linken Tabelle, auch ohne Treffer rechts. Dort stehen dann NULL-Werte. Ideal, um „ohne Bestellung“ zu finden.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT k.name, COUNT(b.id) AS anzahl\nFROM kunde k\nLEFT JOIN bestellung b ON b.kunde_id = k.id\nGROUP BY k.id\nORDER BY k.id;","out":"Ada | 2\nBo | 1\nCy | 0","pitfall":"Bedingungen auf die rechte Tabelle gehören in ON, nicht in WHERE. Ein WHERE auf rechte Spalten macht den LEFT JOIN wieder zum INNER JOIN.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-group","cat":"Aggregation","term":"GROUP BY und HAVING","syntax":"GROUP BY spalte HAVING aggregat > wert","text":"GROUP BY fasst Zeilen zu Gruppen zusammen, Aggregatfunktionen rechnen je Gruppe. WHERE filtert vorher einzelne Zeilen, HAVING filtert danach ganze Gruppen.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT kunde_id, SUM(betrag) AS summe\nFROM bestellung\nGROUP BY kunde_id\nHAVING SUM(betrag) > 15;","out":"1 | 26","pitfall":"Alle nicht aggregierten Spalten im SELECT müssen im GROUP BY stehen (MariaDB im Modus ONLY_FULL_GROUP_BY).","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-aggregate","cat":"Aggregation","term":"COUNT, SUM, AVG, MIN, MAX","syntax":"COUNT(*)  COUNT(spalte)  SUM(…)  AVG(…)","text":"Fassen viele Zeilen zu einem Wert zusammen. COUNT(*) zählt Zeilen, COUNT(spalte) nur Zeilen mit Wert (ohne NULL).","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT COUNT(*), COUNT(stadt), SUM(id), AVG(id), MIN(name), MAX(name) FROM kunde;","out":"3 | 2 | 6 | 2.0 | Ada | Cy","pitfall":"AVG und SUM ignorieren NULL. Bei komplett leerer Gruppe liefert SUM NULL, nicht 0. COALESCE(SUM(x), 0) nutzen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-subquery","cat":"Aggregation","term":"Unterabfrage","syntax":"WHERE spalte IN (SELECT …)","text":"Eine Abfrage innerhalb einer anderen. IN (SELECT …) prüft, ob ein Wert in einer Ergebnisliste vorkommt. EXISTS fragt, ob es überhaupt Treffer gibt.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde\nWHERE id IN (SELECT kunde_id FROM bestellung WHERE betrag > 10)\nORDER BY name;","out":"Ada\nBo","pitfall":"NOT IN (SELECT …) liefert nichts, sobald die Unterabfrage ein NULL enthält. NOT EXISTS ist hier sicherer.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-case","cat":"Abfragen","term":"CASE und COALESCE","syntax":"CASE WHEN … THEN … ELSE … END    COALESCE(a, b)","text":"CASE wählt je Zeile einen Wert nach Bedingungen. COALESCE liefert das erste Argument, das nicht NULL ist, und ersetzt so fehlende Werte.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name,\n  CASE WHEN stadt = 'Berlin' THEN 'Hauptstadt' ELSE 'andere' END AS art,\n  COALESCE(stadt, 'unbekannt') AS ort\nFROM kunde ORDER BY id;","out":"Ada | Hauptstadt | Berlin\nBo | andere | Hamburg\nCy | andere | unbekannt","pitfall":"Für Cy ist stadt = 'Berlin' weder wahr noch falsch (NULL), deshalb greift der ELSE-Zweig. NULL gesondert behandeln, wenn es einen Unterschied macht.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-cte","cat":"Abfragen","term":"WITH (CTE)","syntax":"WITH name AS (SELECT …) SELECT … FROM name","text":"Benennt eine Zwischenabfrage und macht komplexe Abfragen lesbar. Sie wird wie eine temporäre Tabelle verwendet.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"WITH summen AS (\n  SELECT kunde_id, SUM(betrag) AS s FROM bestellung GROUP BY kunde_id\n)\nSELECT k.name, summen.s\nFROM summen JOIN kunde k ON k.id = summen.kunde_id\nORDER BY summen.s DESC;","out":"Ada | 26\nBo | 12","pitfall":"WITH ist in MariaDB ab Version 10.2 verfügbar. Auf älteren Servern gibt es einen Syntaxfehler.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-union","cat":"Abfragen","term":"UNION","syntax":"SELECT … UNION [ALL] SELECT …","text":"Hängt die Ergebnisse zweier Abfragen aneinander. UNION entfernt Doppelte, UNION ALL behält sie und ist schneller. Beide Abfragen brauchen gleich viele Spalten gleichen Typs.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"SELECT name FROM kunde WHERE id = 1\nUNION\nSELECT name FROM kunde WHERE id = 3;","out":"Ada\nCy","pitfall":"Die Spaltennamen kommen von der ersten Abfrage. Die Reihenfolge der Spalten in beiden Abfragen muss übereinstimmen.","lesson":"mariadb-m1-l3","tested":true},{"id":"sql-transaction","cat":"Transaktionen","term":"BEGIN, COMMIT, ROLLBACK","syntax":"START TRANSACTION; … COMMIT;    ROLLBACK;","text":"Fasst mehrere Änderungen zu einer Einheit zusammen: Entweder alles wird übernommen (COMMIT) oder alles zurückgenommen (ROLLBACK). In MariaDB beginnt man mit START TRANSACTION oder BEGIN.","setup":"CREATE TABLE kunde (id INTEGER PRIMARY KEY, name TEXT NOT NULL, stadt TEXT);\nCREATE TABLE bestellung (id INTEGER PRIMARY KEY, kunde_id INTEGER REFERENCES kunde(id), betrag INTEGER);\nINSERT INTO kunde VALUES (1, 'Ada', 'Berlin'), (2, 'Bo', 'Hamburg'), (3, 'Cy', NULL);\nINSERT INTO bestellung VALUES (1, 1, 20), (2, 1, 6), (3, 2, 12);","code":"BEGIN;\nUPDATE bestellung SET betrag = 0 WHERE id = 1;\nROLLBACK;\nSELECT betrag FROM bestellung WHERE id = 1;","out":"20","pitfall":"Transaktionen funktionieren nur mit transaktionsfähigen Engines (InnoDB). Lange offene Transaktionen halten Sperren und blockieren andere.","lesson":"mariadb-m1-l4","tested":true},{"id":"sql-index","cat":"Leistung","term":"CREATE INDEX und EXPLAIN","syntax":"CREATE INDEX name ON tabelle (spalte);    EXPLAIN SELECT …","text":"Ein Index beschleunigt Suche und Sortierung nach einer Spalte. EXPLAIN zeigt, ob die Abfrage ihn nutzt, statt die ganze Tabelle zu lesen.","code":"CREATE INDEX idx_bestellung_kunde ON bestellung (kunde_id);\nEXPLAIN SELECT * FROM bestellung WHERE kunde_id = 1;","pitfall":"Jeder Index macht Schreibzugriffe langsamer und braucht Speicher. Nur anlegen, wenn EXPLAIN und echte Abfragen es zeigen, nicht auf Verdacht.","lesson":"mariadb-m1-l5","tested":false},{"id":"sql-placeholder","cat":"Sicherheit","term":"Platzhalter (Prepared Statement)","syntax":"SELECT … WHERE id = ?    WHERE id = :id","text":"Das SQL steht fest, die Werte werden getrennt übergeben. So kann Nutzereingabe nie als SQL-Befehl ausgeführt werden. Das gilt in PHP (PDO), Java (PreparedStatement) und anderen Sprachen.","code":"-- PHP (PDO)\n$stmt = $pdo->prepare('SELECT * FROM kunde WHERE name = :name');\n$stmt->execute(['name' => $eingabe]);\n\n-- Java (JDBC)\nvar ps = connection.prepareStatement(\"SELECT * FROM kunde WHERE name = ?\");\nps.setString(1, eingabe);","pitfall":"Platzhalter gelten für Werte, nicht für Tabellen-, Spalten- oder Sortierbezeichner. Dafür eine feste Liste erlaubter Namen verwenden.","lesson":"mariadb-m1-l3","tested":false},{"id":"sql-grant","cat":"Sicherheit","term":"GRANT und REVOKE","syntax":"GRANT SELECT, INSERT ON db.* TO 'nutzer'@'host';","text":"Vergibt und entzieht Rechte. Anwendungen bekommen ein eigenes Konto mit den kleinsten nötigen Rechten (Least Privilege), nicht den Administrator.","code":"CREATE USER 'shop_app'@'localhost' IDENTIFIED BY '…';\nGRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO 'shop_app'@'localhost';\nREVOKE DELETE ON shop.* FROM 'shop_app'@'localhost';","pitfall":"Passwörter nie im Skript und nie im Repository speichern. Sie gehören in Umgebungsvariablen oder einen Secret-Speicher.","lesson":"mariadb-m1-l6","tested":false}]},{"id":"git","label":"Git","codeLang":"bash","intro":"Versionsverwaltung im Terminal. Jeder Befehl beginnt mit „git“. Die Beispiele zeigen jeweils den Ausgangszustand und das Ergebnis.","notice":"Die Beispiele sind in einem frischen Testrepository ausgeführt und geprüft. Meldungen erscheinen hier auf Englisch; Git zeigt sie je nach Einstellung auch deutsch.","runner":"Git","entries":[{"id":"git-config","cat":"Einrichten","term":"git config","syntax":"git config --global user.name \"Name\"","text":"Setzt Einstellungen. Name und E-Mail erscheinen in jedem Commit. --global gilt für alle Repositories, ohne die Option nur für das aktuelle.","code":"git config user.name \"Ada Lovelace\"\ngit config --get user.name","out":"Ada Lovelace","pitfall":"Die E-Mail-Adresse aus der Konfiguration steht öffentlich in jedem Commit. Bei öffentlichen Repositories eine Noreply-Adresse verwenden.","lesson":"m61-l2","tested":true},{"id":"git-init","cat":"Einrichten","term":"git init und git clone","syntax":"git init    git clone <url>","text":"init macht aus einem Ordner ein neues Repository (versteckter Ordner .git). clone lädt ein vorhandenes Repository samt Verlauf von einer Adresse herunter.","code":"git status -sb","out":"## No commits yet on main","pitfall":"Den Ordner .git nie von Hand verändern oder löschen: Er enthält den gesamten Verlauf.","lesson":"m61-l2","tested":true},{"id":"git-status","cat":"Grundlagen","term":"git status","syntax":"git status    git status -sb","text":"Zeigt, was sich geändert hat: neu (??), geändert ( M), bereits vorgemerkt (M ). Die Kurzform -s ist knapp, -b zeigt zusätzlich den Branch.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo neu > a.txt\necho zusaetzlich >> datei.txt\ngit status --short","out":" M datei.txt\n?? a.txt","pitfall":"Vor jedem Commit und vor jedem Befehl, der Änderungen verwirft, git status lesen. Es kostet nichts und verhindert Überraschungen.","lesson":"m61-l3","tested":true},{"id":"git-add","cat":"Grundlagen","term":"git add","syntax":"git add <datei>    git add -p","text":"Merkt Änderungen für den nächsten Commit vor (Staging-Bereich). Mit -p wählt man einzelne Abschnitte einer Datei aus.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo zwei >> datei.txt\ngit add datei.txt\ngit status --short","out":"M  datei.txt","pitfall":"git add . nimmt alles mit, auch versehentlich Geheimnisse und Build-Ordner. Vorher .gitignore pflegen und git status prüfen.","lesson":"m61-l3","tested":true},{"id":"git-commit","cat":"Grundlagen","term":"git commit","syntax":"git commit -m \"Nachricht\"    git commit --amend","text":"Speichert die vorgemerkten Änderungen als Schnappschuss im Verlauf. Die Nachricht erklärt das Warum. --amend ändert den letzten, noch nicht veröffentlichten Commit.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo zwei >> datei.txt\ngit commit -q -am \"feat: zweite Zeile ergänzen\"\ngit log --format=%s -n 2","out":"feat: zweite Zeile ergänzen\ninit","pitfall":"Commits, die schon gepusht wurden, nicht mit --amend verändern. Das schreibt den gemeinsamen Verlauf um.","lesson":"m61-l4","tested":true},{"id":"git-diff","cat":"Grundlagen","term":"git diff","syntax":"git diff    git diff --staged    git diff a..b","text":"Zeigt Unterschiede. Ohne Option: Arbeitsverzeichnis gegen Staging. Mit --staged: Staging gegen letzten Commit.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo zwei >> datei.txt\ngit diff --numstat\ngit add datei.txt\ngit diff --staged --numstat","out":"1\t0\tdatei.txt\n1\t0\tdatei.txt","pitfall":"Nach git add zeigt git diff nichts mehr. Die vorgemerkten Änderungen sieht man nur mit --staged.","lesson":"m61-l3","tested":true},{"id":"git-log","cat":"Grundlagen","term":"git log","syntax":"git log --oneline --graph    git log --format=%s    git log -S\"text\"","text":"Zeigt den Verlauf. --oneline kürzt jeden Commit auf eine Zeile, --graph zeichnet Abzweigungen. Mit -S findet man Commits, die einen bestimmten Text hinzugefügt oder entfernt haben.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git log --format=%s\ngit log -S\"zwei\" --format=\"gefunden in: %s\"","out":"zweite Zeile\ninit\ngefunden in: zweite Zeile","pitfall":"git log zeigt nur den aktuellen Branch. Für alle Zweige --all verwenden.","lesson":"m64-l3","tested":true},{"id":"git-gitignore","cat":"Grundlagen","term":".gitignore","syntax":".env\nnode_modules/\n*.log","text":"Textdatei im Projekt mit Mustern für Dateien, die Git ignorieren soll: Geheimnisse, Abhängigkeiten, Build-Ergebnisse. Sie wirkt nur auf noch nicht versionierte Dateien.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"printf '.env\\nnode_modules/\\n' > .gitignore\necho GEHEIM=1 > .env\ngit status --short","out":"?? .gitignore","pitfall":"Wurde eine Datei schon committet, hilft .gitignore nicht mehr. Ein einmal veröffentlichtes Geheimnis ist verbrannt und muss erneuert werden.","lesson":"m61-l5","tested":true},{"id":"git-branch","cat":"Branches","term":"git switch und git branch","syntax":"git switch -c <name>    git switch <name>    git branch","text":"switch wechselt den Branch, -c legt einen neuen an. Ein Branch ist nur ein beweglicher Zeiger auf einen Commit.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -c feature/login\ngit branch --show-current","out":"feature/login","pitfall":"Vor dem Wechsel Änderungen committen oder mit git stash sichern, sonst verweigert Git den Wechsel oder nimmt sie mit.","lesson":"m62-l1","tested":true},{"id":"git-merge","cat":"Branches","term":"git merge","syntax":"git merge <branch>    git merge --no-ff <branch>","text":"Führt die Änderungen eines anderen Branches in den aktuellen zusammen. Mit --no-ff entsteht immer ein eigener Merge-Commit, der die Abzweigung im Verlauf sichtbar lässt.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -q -c feature\necho feature > f.txt\ngit add f.txt\ngit commit -q -m \"feat: f.txt\"\ngit switch -q main\ngit merge -q --no-ff feature -m \"merge feature\"\ngit log --format=%s","out":"merge feature\nfeat: f.txt\ninit","pitfall":"Gemergt wird immer in den Branch, auf dem man gerade steht. Vorher mit git branch --show-current prüfen.","lesson":"m62-l2","tested":true},{"id":"git-conflict","cat":"Branches","term":"Merge-Konflikt","syntax":"<<<<<<< HEAD … ======= … >>>>>>> branch","text":"Ändern zwei Branches dieselbe Stelle, kann Git nicht entscheiden. Es markiert die Stelle in der Datei: oben die eigene Version (HEAD), unten die fremde. Man wählt aus, entfernt die Markierungen, fügt die Datei hinzu und schließt mit einem Commit ab.","setup":"echo a > f.txt\ngit add f.txt\ngit commit -q -m base\ngit switch -q -c feature\necho c > f.txt\ngit commit -q -am feature-change\ngit switch -q main\necho b > f.txt\ngit commit -q -am main-change","code":"git merge feature || true\ncat f.txt","out":"Auto-merging f.txt\nCONFLICT (content): Merge conflict in f.txt\nAutomatic merge failed; fix conflicts and then commit the result.\n<<<<<<< HEAD\nb\n=======\nc\n>>>>>>> feature","pitfall":"Die Markierungen <<<<<<<, ======= und >>>>>>> nie committen. Mit git merge --abort kommt man zum Zustand vor dem Merge zurück. Die Meldungen erscheinen je nach Spracheinstellung deutsch oder englisch.","lesson":"m62-l3","tested":true},{"id":"git-rebase","cat":"Branches","term":"git rebase","syntax":"git rebase <basis>","text":"Setzt die Commits des aktuellen Branches auf eine neue Basis, als wären sie erst jetzt entstanden. Das Ergebnis ist ein gerader Verlauf ohne Merge-Commit.","setup":"echo a > f.txt\ngit add f.txt\ngit commit -q -m base\ngit switch -q -c feature\necho x > x.txt\ngit add x.txt\ngit commit -q -m feature-commit\ngit switch -q main\necho y > y.txt\ngit add y.txt\ngit commit -q -m main-commit","code":"git switch -q feature\ngit rebase -q main\ngit log --format=%s","out":"feature-commit\nmain-commit\nbase","pitfall":"Nie Commits umschreiben (rebase, amend, reset), die andere schon geholt haben. Nach einem Rebase eines geteilten Branches wäre ein Force-Push nötig.","lesson":"m62-l4","tested":true},{"id":"git-stash","cat":"Branches","term":"git stash","syntax":"git stash    git stash pop    git stash list","text":"Legt nicht committete Änderungen beiseite und stellt den sauberen Zustand her. pop holt sie zurück. Praktisch, wenn man kurz den Branch wechseln muss.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo wip >> datei.txt\ngit stash -q\necho \"sauber: $(git status --short | wc -l | tr -d ' ')\"\ngit stash pop -q\ngit status --short","out":"sauber: 0\n M datei.txt","pitfall":"Neue, noch nicht versionierte Dateien nimmt git stash nicht mit. Dafür -u angeben.","lesson":"m62-l5","tested":true},{"id":"git-cherrypick","cat":"Branches","term":"git cherry-pick","syntax":"git cherry-pick <commit>","text":"Übernimmt einen einzelnen Commit von einem anderen Branch als neuen Commit. Praktisch für einen Bugfix, der auch auf einem anderen Zweig gebraucht wird.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git switch -q -c fix\necho fix > fix.txt\ngit add fix.txt\ngit commit -q -m \"fix: kleiner Fehler\"\ngit switch -q main\ngit cherry-pick fix > /dev/null\ngit log --format=%s -n 1","out":"fix: kleiner Fehler","pitfall":"Der Commit existiert danach doppelt (mit verschiedenen Hashes). Wird später der ganze Branch gemergt, kann das Konflikte erzeugen.","lesson":"m62-l5","tested":true},{"id":"git-remote","cat":"Zusammenarbeit","term":"git remote, push, fetch, pull","syntax":"git remote add origin <url>    git push -u origin main    git fetch    git pull","text":"Ein Remote ist ein Repository auf einem Server. push lädt eigene Commits hoch, fetch holt fremde Commits, ohne etwas zu verändern, pull ist fetch plus Zusammenführung.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\nR=$(mktemp -d)\ngit init -q --bare \"$R\"\ngit remote add origin \"$R\"","code":"git push -q -u origin main\ngit status -sb | head -n 1","out":"## main...origin/main","pitfall":"Mit git pull --ff-only holt man sicher: Es bricht ab, statt unbemerkt Merge-Commits zu erzeugen. Vor einem push immer erst fetch oder pull.","lesson":"m63-l1","tested":true},{"id":"git-restore","cat":"Rückgängig machen","term":"git restore","syntax":"git restore <datei>    git restore --staged <datei>","text":"Verwirft Änderungen in einer Datei und stellt den Stand des letzten Commits wieder her. Mit --staged nimmt man nur die Vormerkung zurück und behält die Änderung.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"echo kaputt > datei.txt\ngit restore datei.txt\ncat datei.txt","out":"eins","pitfall":"git restore ohne --staged verwirft nicht gesicherte Änderungen endgültig. Es gibt keine Rückgängig-Funktion dafür.","lesson":"m64-l1","tested":true},{"id":"git-reset","cat":"Rückgängig machen","term":"git reset","syntax":"git reset --soft HEAD~1    git reset --hard <commit>","text":"Setzt den Branch auf einen früheren Commit. --soft behält die Änderungen vorgemerkt, --mixed (Standard) behält sie im Arbeitsverzeichnis, --hard verwirft sie.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git reset --soft HEAD~1\ngit log --format=%s\ngit status --short","out":"init\nM  datei.txt","pitfall":"--hard verwirft nicht committete Arbeit unwiederbringlich. Vorher git status und notfalls git stash.","lesson":"m64-l1","tested":true},{"id":"git-revert","cat":"Rückgängig machen","term":"git revert","syntax":"git revert <commit>","text":"Macht einen Commit rückgängig, indem ein neuer Commit mit den umgekehrten Änderungen entsteht. Der Verlauf bleibt erhalten, deshalb ist das die Wahl für bereits veröffentlichte Commits.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git revert --no-edit HEAD > /dev/null\ngit log --format=%s -n 1\ncat datei.txt","out":"Revert \"zweite Zeile\"\neins","pitfall":"Reset für lokale, noch nicht geteilte Commits, revert für veröffentlichte. Beides nicht verwechseln.","lesson":"m64-l1","tested":true},{"id":"git-reflog","cat":"Rückgängig machen","term":"git reflog","syntax":"git reflog","text":"Das Protokoll aller Bewegungen von HEAD, auch nach einem harten Reset. Mit dem Hash daraus holt man „verlorene“ Commits zurück (git reset --hard <hash>).","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'\necho zwei >> datei.txt\ngit commit -q -am 'zweite Zeile'","code":"git reset -q --hard HEAD~1\ngit reflog --format=%gs","out":"reset: moving to HEAD~1\ncommit: zweite Zeile\ncommit (initial): init","pitfall":"Der Reflog ist nur lokal und wird nach einigen Wochen aufgeräumt. Er ersetzt kein Backup.","lesson":"m64-l2","tested":true},{"id":"git-tag","cat":"Zusammenarbeit","term":"git tag","syntax":"git tag -a v1.0.0 -m \"Release\"    git push --tags","text":"Markiert einen Commit dauerhaft, meist für Releases. Annotierte Tags (-a) tragen zusätzlich Autor, Datum und Nachricht.","setup":"echo eins > datei.txt\ngit add datei.txt\ngit commit -q -m 'init'","code":"git tag -a v1.0.0 -m \"Erste Version\"\ngit tag","out":"v1.0.0","pitfall":"Tags werden von git push nicht automatisch hochgeladen. Dafür git push origin v1.0.0 oder --tags.","lesson":"m61-l4","tested":true},{"id":"git-blame","cat":"Fehler finden","term":"git blame und git bisect","syntax":"git blame <datei>    git bisect start / good / bad","text":"blame zeigt zu jeder Zeile, wer sie wann geändert hat. bisect findet per Halbierung den Commit, der einen Fehler eingeführt hat: Man markiert einen guten und einen schlechten Stand, Git schlägt jeweils den mittleren vor.","code":"git blame -L 1,5 datei.txt\n\ngit bisect start\ngit bisect bad            # aktueller Stand ist kaputt\ngit bisect good v1.0.0    # dieser Stand war in Ordnung\n# … testen, dann je Schritt: git bisect good  oder  git bisect bad\ngit bisect reset          # am Ende zurück","pitfall":"blame zeigt, wer die Zeile zuletzt geändert hat, nicht unbedingt, wer den Fehler verursacht hat. Es dient der Nachfrage, nicht der Schuldzuweisung.","lesson":"m64-l3","tested":false},{"id":"git-hook","cat":"Fehler finden","term":"Git-Hook","syntax":".git/hooks/pre-commit","text":"Ein Skript, das Git vor oder nach bestimmten Aktionen ausführt, etwa vor jedem Commit Tests oder Formatierung. Bricht es mit einem Fehlercode ab, wird der Commit verweigert.","code":"#!/bin/sh\n# .git/hooks/pre-commit (ausführbar machen: chmod +x)\nnpm run lint || {\n  echo \"Lint fehlgeschlagen, Commit abgebrochen\"\n  exit 1\n}","pitfall":"Hooks liegen in .git und werden nicht mit gepusht. Das Team nutzt dafür ein Werkzeug (z. B. Husky oder ein Skript), und CI prüft zusätzlich, weil sich Hooks mit --no-verify umgehen lassen.","lesson":"m64-l4","tested":false}]},{"id":"abap","label":"ABAP","codeLang":"abap","intro":"Sprache der SAP-Systeme. Jede Anweisung endet mit einem Punkt, Kommentare beginnen mit \" oder * am Zeilenanfang. Groß- und Kleinschreibung ist egal; üblich ist Kleinschreibung.","notice":"Diese Beispiele sind nicht in einem SAP-System ausgeführt oder compiliert. Sie folgen der modernen ABAP-Syntax; vor dem Einsatz im eigenen System prüfen.","runner":"","entries":[{"id":"abap-data","cat":"Grundlagen","term":"DATA und inline DATA( )","syntax":"DATA name TYPE typ.    DATA(name) = ausdruck.","text":"DATA legt eine Variable mit Typ an. Mit der Inline-Deklaration DATA(name) = … leitet ABAP den Typ aus der rechten Seite ab. Der Startwert ist bei TYPE i die 0, bei TYPE string der leere Text.","code":"DATA zaehler TYPE i VALUE 5.\nDATA(text) = |Hallo|.\nzaehler = zaehler + 1.","pitfall":"Kettensätze wie DATA: a TYPE i, b TYPE i. sind erlaubt, werden aber schnell unübersichtlich. Eine Anweisung pro Zeile.","lesson":"abap-m7-l0","tested":false},{"id":"abap-types","cat":"Grundlagen","term":"Elementare Typen","syntax":"i  int8  p  f  string  c  d  t  xstring","text":"i und int8 sind ganze Zahlen, p ist die gepackte Dezimalzahl (für Geldbeträge), f die Gleitkommazahl, string ein Text beliebiger Länge, c ein Text fester Länge, d das Datum, t die Uhrzeit.","code":"DATA betrag TYPE p LENGTH 8 DECIMALS 2 VALUE '19.99'.\nDATA datum  TYPE d.\ndatum = sy-datum.","pitfall":"Für Geld p (oder DDIC-Typen mit Währung) statt f verwenden, sonst entstehen Rundungsfehler. Typ c schneidet zu lange Werte stillschweigend ab.","lesson":"abap-m7-l1","tested":false},{"id":"abap-constants","cat":"Grundlagen","term":"CONSTANTS","syntax":"CONSTANTS name TYPE typ VALUE wert.","text":"Legt einen unveränderlichen Wert fest. Er lässt sich nicht überschreiben, und der Compiler meldet Änderungsversuche.","code":"CONSTANTS max_versuche TYPE i VALUE 3.","pitfall":"Magische Zahlen im Code vermeiden: Besser eine Konstante mit sprechendem Namen.","lesson":"abap-m7-l0","tested":false},{"id":"abap-string-template","cat":"Strings","term":"String-Template | |","syntax":"|Text { ausdruck }|","text":"Text in senkrechten Strichen, in dem Ausdrücke in geschweiften Klammern ausgewertet werden. Mit Formatoptionen: { datum DATE = USER }. Der Zusammenbau mit && verkettet Texte.","code":"DATA(name) = `Ada`.\nDATA(gruss) = |Hallo { name }, Summe: { 2 + 3 }|.\nDATA(lang) = strlen( gruss ).","pitfall":"Mit Backticks (`…`) entsteht ein Text vom Typ string, mit Hochkommas ('…') ein Text vom Typ c, bei dem Leerzeichen am Ende verloren gehen.","lesson":"abap-m7-l2","tested":false},{"id":"abap-if","cat":"Kontrollfluss","term":"IF, ELSEIF, ELSE, CASE","syntax":"IF bedingung. … ELSEIF … ELSE. … ENDIF.","text":"Verzweigung nach Bedingung. CASE wählt nach einem Wert. Vergleichsoperatoren: = <> < > <= >=, außerdem IS INITIAL, IS NOT INITIAL, IS BOUND und CO, CS, CP für Textmuster.","code":"IF punkte >= 70.\n  ergebnis = `bestanden`.\nELSE.\n  ergebnis = `weiter üben`.\nENDIF.\n\nCASE status.\n  WHEN 'A' OR 'B'.\n    \" …\n  WHEN OTHERS.\n    \" …\nENDCASE.","pitfall":"Bei CASE ohne WHEN OTHERS passiert bei unbekanntem Wert nichts. Fehlerfälle ausdrücklich behandeln.","lesson":"abap-m7-l0","tested":false},{"id":"abap-cond-switch","cat":"Kontrollfluss","term":"COND und SWITCH","syntax":"COND #( WHEN … THEN … ELSE … )    SWITCH #( wert WHEN … THEN … )","text":"Ausdrücke mit Rückgabewert statt Anweisungen. COND wertet Bedingungen nacheinander aus, SWITCH wählt nach einem Wert.","code":"DATA(art) = COND string( WHEN betrag > 1000 THEN `groß`\n                         WHEN betrag > 100  THEN `mittel`\n                         ELSE `klein` ).\nDATA(tag) = SWITCH string( wochentag WHEN 6 OR 7 THEN `Wochenende` ELSE `Werktag` ).","pitfall":"Ohne ELSE liefert COND bei keinem Treffer den Initialwert des Typs. Das ist leicht zu übersehen.","lesson":"abap-m7-l2","tested":false},{"id":"abap-loop","cat":"Schleifen","term":"DO, WHILE, LOOP AT","syntax":"DO n TIMES. … ENDDO.    WHILE bedingung. … ENDWHILE.    LOOP AT tabelle INTO DATA(zeile). … ENDLOOP.","text":"DO wiederholt n-mal, WHILE solange eine Bedingung gilt, LOOP AT läuft über eine interne Tabelle. sy-index zählt in DO/WHILE, sy-tabix in LOOP AT. EXIT beendet, CONTINUE springt weiter.","code":"DO 3 TIMES.\n  WRITE / sy-index.\nENDDO.\n\nLOOP AT bestellungen INTO DATA(bestellung) WHERE status = 'OFFEN'.\n  summe = summe + bestellung-betrag.\nENDLOOP.","pitfall":"Eine Tabelle während LOOP AT zu ändern ist riskant. Zum Löschen besser DELETE … WHERE außerhalb der Schleife verwenden.","lesson":"abap-m7-l0","tested":false},{"id":"abap-itab","cat":"Interne Tabellen","term":"Tabellentypen","syntax":"TYPE STANDARD TABLE OF …    SORTED TABLE … WITH UNIQUE KEY …    HASHED TABLE … WITH UNIQUE KEY …","text":"STANDARD ist eine Liste, die per Index zugänglich ist, SORTED hält sich sortiert und sucht binär, HASHED sucht per Schlüssel in konstanter Zeit. Der Tabellentyp sollte zum Zugriffsmuster passen.","code":"TYPES: BEGIN OF ty_kunde,\n         id   TYPE i,\n         name TYPE string,\n       END OF ty_kunde.\nDATA kunden TYPE HASHED TABLE OF ty_kunde WITH UNIQUE KEY id.","pitfall":"READ TABLE auf eine STANDARD-Tabelle mit Schlüssel sucht linear. Bei großen Tabellen ist das ein Leistungsproblem: SORTED oder HASHED wählen.","lesson":"abap-m8-l1","tested":false},{"id":"abap-itab-ops","cat":"Interne Tabellen","term":"APPEND, INSERT, READ TABLE, DELETE","syntax":"APPEND zeile TO tab.    READ TABLE tab INTO … WITH KEY …    tab[ id = 1 ]","text":"APPEND hängt an, INSERT fügt an einer Stelle oder in sortierte Tabellen ein, DELETE entfernt. Der Tabellenausdruck tab[ … ] liest eine Zeile und löst CX_SY_ITAB_LINE_NOT_FOUND aus, wenn sie fehlt. line_exists( ) prüft vorher.","code":"APPEND VALUE #( id = 1 name = `Ada` ) TO kunden.\n\nIF line_exists( kunden[ id = 1 ] ).\n  DATA(kunde) = kunden[ id = 1 ].\nENDIF.\n\nREAD TABLE kunden WITH KEY id = 2 TRANSPORTING NO FIELDS.\nIF sy-subrc <> 0.\n  \" nicht gefunden\nENDIF.","pitfall":"sy-subrc nach READ TABLE immer prüfen. Wer ihn vergisst, arbeitet mit der leeren oder alten Zeile weiter.","lesson":"abap-m8-l1","tested":false},{"id":"abap-value-for","cat":"Interne Tabellen","term":"VALUE, FOR, REDUCE, FILTER","syntax":"VALUE #( FOR x IN tab ( … ) )    REDUCE typ( INIT … FOR … NEXT … )    FILTER #( tab WHERE … )","text":"Ausdrucksbasierte Verarbeitung von Tabellen. VALUE #( ) baut Strukturen und Tabellen, FOR wandelt Zeilen um, REDUCE verdichtet zu einem Wert, FILTER behält passende Zeilen.","code":"DATA(namen) = VALUE string_table( FOR k IN kunden ( k-name ) ).\n\nDATA(summe) = REDUCE i( INIT s = 0\n                        FOR b IN bestellungen\n                        NEXT s = s + b-betrag ).\n\nDATA(offene) = FILTER #( bestellungen WHERE status = 'OFFEN' ).","pitfall":"FILTER braucht für die Spalte im WHERE einen sortierten oder Hash-Schlüssel (oder USING KEY). Sonst meldet der Compiler einen Fehler.","lesson":"abap-m7-l2","tested":false},{"id":"abap-select","cat":"Datenbank (Open SQL)","term":"SELECT","syntax":"SELECT feld1, feld2 FROM tabelle WHERE bedingung INTO TABLE @DATA(ergebnis).","text":"Liest Daten aus der Datenbank. In der modernen Syntax stehen Hostvariablen mit @, Felder durch Komma getrennt und INTO am Ende. ORDER BY, GROUP BY, UP TO n ROWS und JOINs gibt es wie in SQL.","code":"SELECT carrid, connid, price\n  FROM sflight\n  WHERE carrid = @carrier\n  ORDER BY price DESCENDING\n  INTO TABLE @DATA(fluege)\n  UP TO 10 ROWS.\n\nIF sy-subrc <> 0.\n  \" keine Treffer\nENDIF.","pitfall":"SELECT in einer Schleife (ein Aufruf je Zeile) ist die häufigste Ursache für langsame Programme. Einmal gesammelt lesen und mit FOR ALL ENTRIES oder JOIN arbeiten.","lesson":"abap-m9-l1","tested":false},{"id":"abap-select-single","cat":"Datenbank (Open SQL)","term":"SELECT SINGLE","syntax":"SELECT SINGLE felder FROM tabelle WHERE … INTO @DATA(zeile).","text":"Liest genau eine Zeile. Mit vollständigem Schlüssel ist das eindeutig, sonst liefert die Datenbank irgendeinen Treffer.","code":"SELECT SINGLE name, ort\n  FROM kunde\n  WHERE id = @kunden_id\n  INTO @DATA(kunde).\nIF sy-subrc = 0.\n  \" kunde-name verwenden\nENDIF.","pitfall":"SELECT SINGLE ohne vollständigen Schlüssel ist nicht deterministisch. Für mehrere mögliche Treffer UP TO 1 ROWS mit ORDER BY verwenden.","lesson":"abap-m9-l1","tested":false},{"id":"abap-modify-db","cat":"Datenbank (Open SQL)","term":"INSERT, UPDATE, DELETE","syntax":"INSERT dbtab FROM @struktur.    UPDATE dbtab SET … WHERE …    DELETE FROM dbtab WHERE …","text":"Ändern Daten in der Datenbank. sy-subrc zeigt den Erfolg. Die Änderung wird erst mit COMMIT WORK dauerhaft, bis dahin ist sie nur in der laufenden Transaktion.","code":"UPDATE kunde SET ort = @neuer_ort WHERE id = @kunden_id.\nIF sy-subrc = 0.\n  COMMIT WORK.\nELSE.\n  ROLLBACK WORK.\nENDIF.","pitfall":"In ABAP Cloud und bei RAP führt man Änderungen nicht über direkte Datenbankzugriffe aus, sondern über EML (MODIFY ENTITIES), damit Validierungen laufen.","lesson":"abap-m17-l1","tested":false},{"id":"abap-method","cat":"Klassen","term":"CLASS, METHODS, METHOD","syntax":"CLASS name DEFINITION. … ENDCLASS.    CLASS name IMPLEMENTATION. … ENDCLASS.","text":"Eine Klasse hat einen Definitionsteil (Schnittstelle) und einen Implementierungsteil. Methoden haben IMPORTING-, EXPORTING-, CHANGING- und RETURNING-Parameter. Mit RETURNING lässt sich die Methode direkt in Ausdrücken verwenden.","code":"CLASS lcl_rechner DEFINITION FINAL.\n  PUBLIC SECTION.\n    METHODS summe\n      IMPORTING a TYPE i b TYPE i\n      RETURNING VALUE(ergebnis) TYPE i.\nENDCLASS.\n\nCLASS lcl_rechner IMPLEMENTATION.\n  METHOD summe.\n    ergebnis = a + b.\n  ENDMETHOD.\nENDCLASS.\n\nDATA(rechner) = NEW lcl_rechner( ).\nDATA(s) = rechner->summe( a = 2 b = 3 ).","pitfall":"Klassen mit FINAL schließen Vererbung aus. Das ist die sichere Standardwahl, solange keine Unterklassen nötig sind.","lesson":"abap-m10-l1","tested":false},{"id":"abap-interface","cat":"Klassen","term":"INTERFACE","syntax":"INTERFACE name PUBLIC. METHODS … ENDINTERFACE.    INTERFACES name.","text":"Ein Interface legt Methoden fest, ohne sie zu implementieren. Klassen binden es mit INTERFACES ein und implementieren die Methoden. So lassen sich Abhängigkeiten austauschbar machen (z. B. für Tests).","code":"INTERFACE lif_zahlung.\n  METHODS bezahlen IMPORTING betrag TYPE p.\nENDINTERFACE.\n\nCLASS lcl_karte DEFINITION.\n  PUBLIC SECTION.\n    INTERFACES lif_zahlung.\nENDCLASS.\n\nCLASS lcl_karte IMPLEMENTATION.\n  METHOD lif_zahlung~bezahlen.\n    \" …\n  ENDMETHOD.\nENDCLASS.","pitfall":"Methoden eines Interfaces spricht man mit dem Präfix an (lif_zahlung~bezahlen). Wer das vergisst, bekommt einen Syntaxfehler.","lesson":"abap-m10-l1","tested":false},{"id":"abap-exception","cat":"Fehler","term":"TRY, CATCH, RAISE EXCEPTION","syntax":"TRY. … CATCH cx_… INTO DATA(fehler). … ENDTRY.    RAISE EXCEPTION NEW cx_…( ).","text":"Klassenbasierte Ausnahmen. TRY fängt sie, CATCH behandelt sie, CLEANUP räumt auf. Eigene Ausnahmen erben von CX_STATIC_CHECK (muss deklariert werden) oder CX_NO_CHECK. get_text( ) liefert die Meldung.","code":"TRY.\n    DATA(ergebnis) = 10 / nenner.\n  CATCH cx_sy_zerodivide INTO DATA(fehler).\n    DATA(meldung) = fehler->get_text( ).\nENDTRY.\n\nRAISE EXCEPTION NEW cx_sy_zerodivide( ).","pitfall":"Nicht CATCH cx_root verwenden: Das fängt auch Fehler, die man nicht behandeln kann. Konkrete Ausnahmeklassen nennen.","lesson":"abap-m10-l4","tested":false},{"id":"abap-fieldsymbol","cat":"Dynamisch","term":"Feldsymbole und Datenreferenzen","syntax":"FIELD-SYMBOLS <fs> TYPE …    ASSIGN … TO <fs>    REF #( … )","text":"Ein Feldsymbol ist ein Zeiger auf vorhandene Daten, Änderungen wirken direkt darauf. Datenreferenzen (REF) sind Zeiger, die man in Variablen speichert. Beim Durchlaufen großer Tabellen vermeiden sie Kopien.","code":"LOOP AT bestellungen ASSIGNING FIELD-SYMBOL(<b>).\n  <b>-betrag = <b>-betrag * 2.\nENDLOOP.","pitfall":"Ein nicht zugewiesenes Feldsymbol führt bei Zugriff zu einem Laufzeitfehler. Mit IS ASSIGNED prüfen.","lesson":"abap-m7-l3","tested":false},{"id":"abap-cds","cat":"CDS und RAP","term":"CDS-View-Entity","syntax":"define view entity Name as select from tabelle { key feld, … }","text":"Datenmodell in der Datenbankschicht, das mit Annotationen (@…) angereichert wird. View-Entities sind die aktuelle Form. Mit Assoziationen (association) beschreibt man Beziehungen, ohne sofort zu joinen.","code":"@AccessControl.authorizationCheck: #CHECK\ndefine view entity ZI_Kunde\n  as select from zkunde\n{\n  key id    as KundenId,\n      name  as Name,\n      ort   as Ort\n}","pitfall":"Eine Zugriffskontrolle (DCL) gehört zu jeder CDS-Entity, die Daten von Nutzern ausliefert. @AccessControl.authorizationCheck: #NOT_REQUIRED nur bewusst und begründet.","lesson":"abap-m11-quellen-brucke-von-select-zu-cds-ein-lesbares-datenmodell-bauen","tested":false},{"id":"abap-rap-bdef","cat":"CDS und RAP","term":"Behavior Definition (RAP)","syntax":"managed implementation in class … unique; define behavior for … { create; update; delete; }","text":"Beschreibt das Verhalten eines Business Objects: welche Operationen erlaubt sind, welche Felder nur lesbar sind, welche Validierungen und Determinationen laufen. „managed“ heißt: Das Framework übernimmt Standard-CRUD und Persistenz.","code":"managed implementation in class zbp_i_kunde unique;\nstrict ( 2 );\n\ndefine behavior for ZI_Kunde alias Kunde\npersistent table zkunde\nlock master\nauthorization master ( instance )\n{\n  create;\n  update;\n  delete;\n  field ( readonly ) KundenId;\n  validation pruefeName on save { create; field Name; }\n}","pitfall":"Validierungen laufen beim Speichern auf dem Server. Eine Prüfung allein in der Oberfläche schützt die Daten nicht.","lesson":"abap-m12-quellen-rap-zuerst-verstehen-daten-verhalten-und-managed-unmanaged","tested":false},{"id":"abap-eml","cat":"CDS und RAP","term":"EML: MODIFY ENTITIES und READ ENTITIES","syntax":"MODIFY ENTITIES OF … ENTITY … CREATE FIELDS ( … ) WITH …","text":"Entity Manipulation Language: Zugriff auf RAP-Business-Objects im Code. Sie durchläuft die Verhaltensdefinition, also Validierungen und Berechtigungen. COMMIT ENTITIES schreibt die Änderungen.","code":"MODIFY ENTITIES OF zi_kunde\n  ENTITY Kunde\n    CREATE FIELDS ( Name Ort )\n    WITH VALUE #( ( %cid = 'k1' Name = `Ada` Ort = `Berlin` ) )\n  FAILED   DATA(failed)\n  REPORTED DATA(reported).\n\nCOMMIT ENTITIES RESPONSE OF zi_kunde\n  FAILED DATA(commit_failed)\n  REPORTED DATA(commit_reported).","pitfall":"Die Ausgaben FAILED und REPORTED immer auswerten. Sonst bleiben abgelehnte Änderungen unbemerkt.","lesson":"abap-m12-quellen-validierung-determination-und-action-mit-eml-auseinanderhalten","tested":false},{"id":"abap-unit","cat":"Tests","term":"ABAP Unit","syntax":"CLASS ltcl_test DEFINITION FOR TESTING … METHODS name FOR TESTING.","text":"Testklassen sind lokal in der zu testenden Klasse und mit FOR TESTING gekennzeichnet. cl_abap_unit_assert=>assert_equals( ) prüft das Ergebnis.","code":"CLASS ltcl_rechner DEFINITION FINAL FOR TESTING\n  RISK LEVEL HARMLESS DURATION SHORT.\n  PRIVATE SECTION.\n    METHODS summe_ist_korrekt FOR TESTING.\nENDCLASS.\n\nCLASS ltcl_rechner IMPLEMENTATION.\n  METHOD summe_ist_korrekt.\n    cl_abap_unit_assert=>assert_equals(\n      act = NEW lcl_rechner( )->summe( a = 2 b = 3 )\n      exp = 5 ).\n  ENDMETHOD.\nENDCLASS.","pitfall":"Tests, die auf echte Datenbanktabellen zugreifen, sind unzuverlässig. Zugriffe über Testdoubles (Test Seams oder Interfaces) ersetzen.","lesson":"abap-m16-l3","tested":false}]}];
